const adventureNameExists = (name, ignoreId = null) => {
    const normalized = normalizeAdventureName(name);
    const folder = normalizeAdventureFolder(name);
    return (adventureRegistry?.adventures || []).some(item => item.id !== ignoreId && (
        String(item.name || "").localeCompare(normalized,"tr",{sensitivity:"base"}) === 0 ||
        String(item.folder || "").localeCompare(folder,"tr",{sensitivity:"base"}) === 0
    ));
};
