const seedAdventureFolder = async (adventure,{migrateLegacy=false}={}) => {
    const paths=adventurePathsFor(adventure),base=paths.base;
    const ensured=await window.__alekGameEnsure(adventure.folder,adventure.mode||"other_realm");
    if(!ensured?.ok)throw new Error(ensured?.error||"Macera SQLite veritabanı oluşturulamadı.");
    await ensureJsonFile(paths.journey, defaultStoryData);
    await ensureJsonFile(paths.characters, defaultCharacterData);
    await ensureJsonFile(paths.locations, defaultLocationData);
    await ensureJsonFile(paths.groups, defaultGroupData);
    await ensureJsonFile(paths.mounts, defaultMountData);
    await ensureJsonFile(paths.forgotten, defaultForgottenData);
    await ensureJsonFile(paths.special, defaultSpecialData);
    await ensureJsonFile(paths.map, defaultMapData);
    await ensureJsonFile(paths.tide, defaultTideData);
    await ensureJsonFile(paths.lore, defaultLoreData);
    await ensureJsonFile(paths.reverie, defaultReverieData, "");
    await ensureJsonFile(paths.mapLibrary, defaultMapLibraryData);
    await ensureJsonFile(paths.harmonizer, defaultHarmonizerData);
    if(migrateLegacy || adventure.coverPolicy==="alekrythae-default"){
        const target=`${base}/Media/Adventure/cover.png`;
        // Kayıt içinde yol dolu olsa bile dosyanın gerçekten mevcut olduğunu garanti et.
        // Önceki paketlerde kayıt yolu vardı fakat fiziksel kapak kopyalanmadığı için kart ◈ gösteriyordu.
        if(await copyBundledAssetBinary("Assets/alekrythae_logo.png",target)) adventure.cover=target;
        else adventure.cover="Assets/alekrythae_logo.png";
    }
};

