const loadAdventureRegistry = async () => {
    const fallback={meta:{schemaVersion:2,app:"Alekrythae Adventure Registry",storage:"portable-sqlite"},activeId:"",adventures:[]};
    const response=await window.__alekRegistryRead();
    let registry=response?.ok&&response.data&&typeof response.data==="object"?response.data:fallback;
    if(!Array.isArray(registry.adventures))registry.adventures=[];
    registry.adventures=registry.adventures.map(item=>({
        id:String(item?.id||makeId("adventure")),
        name:normalizeAdventureName(item?.name||"Adventure")||"Adventure",
        folder:normalizeAdventureFolder(item?.folder||item?.name||"Adventure")||makeId("Adventure"),
        cover:String(item?.cover||""),
        mode:"real_world",
        coverPolicy:String(item?.coverPolicy||"none"),
        createdAt:item?.createdAt||new Date().toISOString(),updatedAt:item?.updatedAt||new Date().toISOString()
    }));
    // Temiz kurulumda registry doğal olarak boştur. Önceki sürüm bunu
    // "aktif macera yok" diye bırakıp ilk otomatik kayıtta boş klasörle
    // SQLite yazmaya çalışıyordu. İlk açılışta kanonik macerayı atomik
    // biçimde oluştur ve bütün varsayılan belgeleri seed et.
    if (!registry.adventures.length) {
        const initialAdventure=defaultAdventureRecord();
        registry.adventures=[initialAdventure];
        registry.activeId=initialAdventure.id;
    }
    const selected=registry.adventures.find(item=>item.id===registry.activeId)||registry.adventures[0]||null;
    registry.activeId=selected?.id||"";
    adventureRegistry=registry;activeAdventure=selected;adventureManagerSelectionId=selected?.id||null;
    if(selected){
        await seedAdventureFolder(selected,{migrateLegacy:false});
        configureAdventurePaths(selected);
    }else{
        Object.keys(DATA_PATHS).forEach(key=>delete DATA_PATHS[key]);
        activeJourneyPath="";activeSavePath="";journeyNotes=[];allSaveFiles=[];
    }
    await writeAdventureRegistry();
};

