const formatDurationSeconds = total => {
    const game=normalizeGameRuntime();
    let seconds=Math.max(0,Math.round(Number(total)||0));
    if(game.mode==="alekrytha"){
        const days=Math.floor(seconds/ALEK_SECONDS_PER_DAY);seconds%=ALEK_SECONDS_PER_DAY;
        const hours=Math.floor(seconds/ALEK_SECONDS_PER_HOUR);seconds%=ALEK_SECONDS_PER_HOUR;
        const minutes=Math.floor(seconds/ALEK_SECONDS_PER_MINUTE);seconds%=ALEK_SECONDS_PER_MINUTE;
        return [[days,"gün"],[hours,"saat"],[minutes,"dakika"],[seconds,"sn"]].filter(([value])=>value>0).map(([value,label])=>`${value} ${label}`).join(" ")||"0 sn";
    }
    const days=Math.floor(seconds/86400);seconds%=86400;const hours=Math.floor(seconds/3600);seconds%=3600;const minutes=Math.floor(seconds/60);seconds%=60;
    return [[days,"gün"],[hours,"sa"],[minutes,"dk"],[seconds,"sn"]].filter(([value])=>value>0).map(([value,label])=>`${value} ${label}`).join(" ")||"0 sn";
};
const estimateSpeechSeconds = text => {
    const raw=String(text||"").trim();if(!raw)return 0;
    // Konuşma hesabının ana girdisi doğrudan karakter sayısıdır. Türkçe için
    // yaklaşık 135 kelime/dakika ve boşluklar dâhil ortalama 6 karakter/kelime,
    // yaklaşık 13,5 karakter/saniye verir. Noktalama ve paragraf solukları ayrıca eklenir.
    const spokenCharacters=raw.replace(/\s+/g," ").length;
    const sentences=(raw.match(/[.!?…]+/g)||[]).length;
    const commas=(raw.match(/[,;:]+/g)||[]).length;
    const paragraphs=Math.max(0,(raw.match(/\n+/g)||[]).length);
    const spoken=spokenCharacters/13.5;
    return Math.max(2,Math.ceil(spoken+sentences*.55+commas*.22+paragraphs*.8));
};
const applyHourlyRecovery=(elapsedSeconds,{healthMultiplier=1,manaMultiplier=1,staminaMultiplier=0,metanetMultiplier=0}={})=>{
    if(!(elapsedSeconds>0)||typeof getAllCharacters!=="function")return {health:0,mana:0,stamina:0,metanet:0,characters:0};
    let healthTotal=0,manaTotal=0,staminaTotal=0,metanetTotal=0,characters=0;
    const runtimeMode=normalizeGameRuntime().mode;
    const hours=elapsedSeconds/(runtimeMode==="alekrytha"?ALEK_SECONDS_PER_HOUR:3600);
    for(const char of getAllCharacters()){
        if(!char||char.isDead)continue;
        ensureEntitySheetFields(char,"character");
        const carry=char.recoveryCarry;
        const rates={
            health:Math.max(0,Number(char.healthRecoveryPerHour)||0)*Math.max(0,Number(healthMultiplier)||0),
            mana:Math.max(0,Number(char.manaRecoveryPerHour)||0)*Math.max(0,Number(manaMultiplier)||0),
            stamina:Math.max(0,Number(char.staminaRecoveryPerHour)||0)*Math.max(0,Number(staminaMultiplier)||0),
            metanet:Math.max(0,Number(char.metanetRecoveryPerHour)||0)*Math.max(0,Number(metanetMultiplier)||0)
        };
        const pools={health:char.health,mana:char.arcanaReserve,stamina:char.stamina,metanet:char.metanet};
        const totals={health:0,mana:0,stamina:0,metanet:0};
        for(const key of Object.keys(pools)){
            const poolValue=Number(carry[key]||0)+rates[key]*hours;
            const gain=Math.floor(poolValue+1e-9);
            carry[key]=poolValue-gain;
            const pool=pools[key],before=Number(pool.current)||0;
            if(gain>0)pool.current=Math.min(Number(pool.maximum)||1,before+gain);
            totals[key]=Math.max(0,(Number(pool.current)||0)-before);
        }
        syncCharacterThresholdStates(char);
        healthTotal+=totals.health;manaTotal+=totals.mana;staminaTotal+=totals.stamina;metanetTotal+=totals.metanet;characters++;
    }
    return {health:healthTotal,mana:manaTotal,stamina:staminaTotal,metanet:metanetTotal,characters};
};
