    if (kind === "location") c.raceMode = "alekrythae";
    else if (!["alekrythae", "outer"].includes(c.raceMode)) c.raceMode = "alekrythae";
    if (typeof c.alekrythaeRace !== "string" || (!c.alekrythaeRace.trim() && kind !== "location")) c.alekrythaeRace = c.race || (kind === "location" ? "" : "İnsan");
