    if(type==="species"&&normalizeGameRuntime().mode==="alekrytha"){
        const isBeing=!!(entity?.__being||entity?.isBeing||String(entity?.entityType||"")==="being");
        cards=cards.filter(item=>isBeing?item.canonicalAlekrythaRace!==true:item.canonicalAlekrythaRace===true);
    }
