    if(!selected){
        const wanted=String(entity.race||entity.alekrythaeRace||"İnsan").trim().toLocaleLowerCase("tr");
        selected=cards.find(item=>String(item.name||"").trim().toLocaleLowerCase("tr")===wanted)
            ||cards.find(item=>String(item.name||"").trim().toLocaleLowerCase("tr")==="insan")||cards[0]||null;
    }
