// ============== ALAN BAZLI SQLITE KAYDI + GERÇEK TAKVİM ==============
// Her alan aktif Adventure'ın game.db dosyasındaki ayrı belge olarak izlenir.
// Yalnız gerçekten değişen belge güncellenir ve önceki 50 sürümü saklanır.
const __dataBaseline = new Map();
let __dataBaselineReady = false;
const __dataFingerprintValue = (key,value) => {
    const clone = JSON.parse(JSON.stringify(value || {}));
    // Uçucu meta.updatedAt farkı, içerik hiç değişmediği hâlde story/reverie'nin
    // her otomatik kayıtta yeniden yazılmasına yol açıyordu; parmak izinden çıkar.
    if (clone && clone.meta && typeof clone.meta === "object") delete clone.meta.updatedAt;
    return clone;
};
const __dataFingerprint = (key,value,path="") => `${String(path||"")}\u0000${JSON.stringify(__dataFingerprintValue(key,value))}`;
const syncCharacterStoresFromState = () => {
    const specials = [];
    const normals = [];
    (currentState.characters || []).forEach(c => {
        const copy = JSON.parse(JSON.stringify(c));
        if (copy.__special || ["af","mv"].includes(String(copy.externalId || "").toLowerCase())) specials.push(copy);
        else normals.push(copy);
    });
    specialData.specialCharacters = specials;
    characterData.characters = normals;
};
const prepareDataModelForPersistence = () => {
    if(typeof captureAdventureUiState==="function")captureAdventureUiState();
    syncCharacterStoresFromState();
    storyData.settings = currentState.settings || {};
    storyData.meta = Object.assign({}, storyData.meta || {}, { schemaVersion:32, app:"Alekrythae DM Master", storage:"portable-sqlite", gameMode:normalizeGameRuntime().mode, journeyName:String(activeAdventure?.name||DEFAULT_ADVENTURE_NAME), adventureId:String(activeAdventure?.id||""), updatedAt:new Date().toISOString() });
    mapData.meta = Object.assign({}, mapData.meta || {}, { schemaVersion:25, app:"Alekrythae Map Realms" });
    tideData.meta = Object.assign({}, tideData.meta || {}, { schemaVersion:21, app:"Alekrythae Connections" });
    loreData.meta = Object.assign({}, loreData.meta || {}, { schemaVersion:21, app:"Alekrythae Lore" });
    groupData.meta = Object.assign({}, groupData.meta || {}, { schemaVersion:1, app:"Alekrythae Journey Groups" });
    mountData.meta = Object.assign({}, mountData.meta || {}, { schemaVersion:1, app:"Alekrythae Journey Mounts" });
    forgottenData.meta = Object.assign({}, forgottenData.meta || {}, { schemaVersion:1, app:"Alekrythae Forgotten Vault" });
    reverieData.meta = Object.assign({}, reverieData.meta || {}, { schemaVersion:3, app:"Alekrythae Reverie", updatedAt:new Date().toISOString() });
    mapLibraryData.meta = Object.assign({}, mapLibraryData.meta || {}, { schemaVersion:1, app:"Alekrythae Map Library" });
    mapLibraryData.defaultSize = Math.max(60, Number(mapLibraryData.defaultSize) || 280);
    harmonizerData.meta = Object.assign({}, harmonizerData.meta || {}, { schemaVersion:2, app:"Alekrythae Harmonizer" });
    harmonizerData.performance = Object.assign({}, defaultHarmonizerData.performance, harmonizerData.performance || {});
    if (!harmonizerData.harmonizer || typeof harmonizerData.harmonizer !== "object") harmonizerData.harmonizer = {};
};
const dataPersistenceDomains = () => {
    const domains = {
        characters: { path:DATA_PATHS.characters, value:characterData },
        locations: { path:DATA_PATHS.locations, value:locationData },
        groups: { path:DATA_PATHS.groups, value:groupData },
        mounts: { path:DATA_PATHS.mounts, value:mountData },
        forgotten: { path:DATA_PATHS.forgotten, value:forgottenData },
        special: { path:DATA_PATHS.special, value:specialData },
        map: { path:DATA_PATHS.map, value:mapData },
        tide: { path:DATA_PATHS.tide, value:tideData },
        lore: { path:DATA_PATHS.lore, value:loreData },
        reverie: { path:DATA_PATHS.reverie, value:reverieData },
        mapLibrary: { path:DATA_PATHS.mapLibrary, value:mapLibraryData },
        harmonizer: { path:DATA_PATHS.harmonizer, value:harmonizerData }
    };
    // JN seçilmediyse uygulamayı açmak veya takvimde gezinmek yeni dosya üretmez.
    if (activeJourneyPath) domains.story = { path:activeJourneyPath, value:storyData };
    return domains;
};
const captureDataPersistenceBaseline = () => {
    prepareDataModelForPersistence();
    __dataBaseline.clear();
    Object.entries(dataPersistenceDomains()).forEach(([key,domain]) => __dataBaseline.set(key,__dataFingerprint(key,domain.value,domain.path)));
    __dataBaselineReady = true;
};

// ============== v22.4: MAP / TIDE TAM İŞLEM GEÇMİŞİ ==============
// Çizim, resim, raptiye, bağ, Realm ve Section değişikliklerini tek geçmişte tutar.
const __viewHistory = {
    map: { undo: [], redo: [], current: null },
    tide: { undo: [], redo: [], current: null }
};
let __viewHistoryReady = false;
let __viewHistoryApplying = false;
const __viewHistoryValue = kind => kind === "map" ? mapData : tideData;
const __viewHistorySerialize = kind => JSON.stringify(__viewHistoryValue(kind));
const initializeViewHistory = () => {
    __viewHistory.map.undo.length = 0; __viewHistory.map.redo.length = 0;
    __viewHistory.tide.undo.length = 0; __viewHistory.tide.redo.length = 0;
    __viewHistory.map.current = __viewHistorySerialize("map");
    __viewHistory.tide.current = __viewHistorySerialize("tide");
    __viewHistoryReady = true;
};
const recordViewHistoryChange = kind => {
    if (!__viewHistoryReady || __viewHistoryApplying) return;
    const history = __viewHistory[kind];
    const now = __viewHistorySerialize(kind);
    if (history.current === now) return;
    if (history.current != null) history.undo.push(history.current);
    if (history.undo.length > 32) history.undo.splice(0, history.undo.length - 32);
    history.redo.length = 0;
    history.current = now;
};
const canUndoViewHistory = kind => !!__viewHistory[kind]?.undo.length;
const canRedoViewHistory = kind => !!__viewHistory[kind]?.redo.length;
const applyViewHistory = async (kind, direction = "undo") => {
    if (!__viewHistoryReady || !["map","tide"].includes(kind)) return false;
    const history = __viewHistory[kind];
    const source = direction === "redo" ? history.redo : history.undo;
    const target = direction === "redo" ? history.undo : history.redo;
    if (!source.length) { new Notice(direction === "redo" ? "İleri alınacak işlem yok." : "Geri alınacak işlem yok."); return false; }
    const current = __viewHistorySerialize(kind);
    const next = source.pop();
    target.push(current);
    if (target.length > 32) target.splice(0, target.length - 32);
    __viewHistoryApplying = true;
    try {
        if (kind === "map") mapData = JSON.parse(next);
        else tideData = JSON.parse(next);
        history.current = next;
        await persistNewDataModel();
    } finally { __viewHistoryApplying = false; }
    if (kind === "map" && activeV2View === "map") {
        mapPointDraft = null; mapSplineDraft = null; activeMapRuntime = null; renderMap();
    }
    if (kind === "tide" && activeV2View === "connections") {
        connectionLinkStartId = null; connectionLinkMode = false; activeConnectionRuntime = null; renderConnections();
    }
    new Notice(direction === "redo" ? "↷ İşlem ileri alındı." : "↶ İşlem geri alındı.");
    return true;
};

// ============== v21.5: KARAKTER PANELİ GÖRSEL DURUM HAFIZASI ==============
// Bu hafıza yalnız arayüz içindir; JSON verisine yazılmaz. EXP, büyü, görev,
// eşya veya görsel değişikliklerinden sonra açık sekme, kategori, akordeonlar
// ve kaydırma konumu korunur.
const __characterUiState = new Map();
const characterUiKey = char => `${char?.__location ? "location" : "character"}:${String(char?.id ?? char?.externalId ?? `${char?.name || ""}|${char?.surname || ""}`)}`;
const ensureUiSet = value => value instanceof Set ? value : new Set(Array.isArray(value) ? value : []);
const getCharacterUiState = char => {
    const key = characterUiKey(char);
    if(!__characterUiState.has(key)) {
        __characterUiState.set(key, {
            activeTab: "sheet",
            tabScroll: {},
            skill: { activeCat: "fiziksel", scrollByCat: {}, openTargets: new Set() },
            inventory: { scrollTop: 0, openTargets: new Set(), mode: "list" },
            journal: { scrollTop: 0, openTargets: new Set(), mode: "list", taskScrollTop: 0 },
            gorevler: { scrollTop: 0, openTargets: new Set(), mode: "list", taskScrollTop: 0 }
        });
    }
    const state = __characterUiState.get(key);
    state.skill.openTargets = ensureUiSet(state.skill.openTargets);
    state.inventory.openTargets = ensureUiSet(state.inventory.openTargets);
    state.journal.openTargets = ensureUiSet(state.journal.openTargets);
    state.gorevler.openTargets = ensureUiSet(state.gorevler.openTargets);
    return state;
};
const reopenAccordionTargets = (container, selector, openTargets) => {
    if(!container || !(openTargets instanceof Set)) return;
    const triggers = Array.from(container.querySelectorAll(selector));
    openTargets.forEach(targetId => {
        const trigger = triggers.find(el => el.getAttribute("data-target") === targetId);
        const target = trigger ? container.querySelector(`#${targetId}`) : null;
        if(trigger && target && target.style.display === "none") trigger.click();
    });
};
const restoreScrollPosition = (element, value) => {
    if(!element) return;
    const top = Math.max(0, Number(value) || 0);
    requestAnimationFrame(() => { if(element.isConnected) element.scrollTop = top; });
};
