        if(!currentState.settings) currentState.settings = { bgInner: [], bgOuter: [], bgInterval: 5, bgMusic: [], musicState: {idx:0, time:0} };
        if(!currentState.characters || !Array.isArray(currentState.characters)) currentState.characters = [];

