        const ALEK_AMBIANCE_IMAGE_HOLD_SECONDS = 10;
        const ALEK_AMBIANCE_PHASE_OFFSET_MS = 5000;
        const ALEK_AMBIANCE_PHASE_DRIFT_TOLERANCE_MS = 220;
        const ALEK_AMBIANCE_PHASE_WATCHDOG_MS = 2500;
