                // --- 🧠 PRO MOTOR (BETA YOLU İLE HATASIZ ÇÖZÜM) ---
                const callMeggy = async (text) => {
                    let keyContent = "";
                    try { 
                        let keyExists = _hasBridge ? await window.__alekExists("Meggy_API_Key.md") : { ok: false };
                        if(keyExists.ok && keyExists.exists) {
                            const keyFile = app.vault.getAbstractFileByPath("Meggy_API_Key.md");
                            keyContent = (await app.vault.read(keyFile)).trim();
                        } else {
                            throw new Error("API key file not found");
                        }
                    } catch(e) { new Notice("🛑 'Meggy_API_Key.md' bulunamadı!"); return; }

                    if(!keyContent || keyContent.includes("BURAYA")) { new Notice("🛑 Geçerli bir API anahtarı yapıştırın!"); return; }

                    sendBtn.innerText = "Zihin Derinliklerine Bakıyor..."; sendBtn.disabled = true;
                    
                    // JSON Yapısı Düzeltildi: Parts bir ARRAY olmalı
                    const payload = {
                        system_instruction: { 
                            parts: [{ text: "Sen Meggy'sin. Ałek’ryŧhæ evreninin DM asistanısın. Karanlık, edebi, felsefi ve acımasız konuş. 'tanrı' kelimesini asla kullanma; eski çağlara ait olan her şey için daima 'Antik' sözcüğünü kullan." }] 
                        },
                        contents: [...(currentState.settings.meggyHistory || []), { role: "user", parts: [{ text: text }] }]
                    };

                    try {
                        // ADRES v1beta OLARAK DEĞİŞTİRİLDİ (System Instruction hatasını çözer)
                        // Model adını 'gemini-3-pro' olarak güncellediğini varsayarsak:
							const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite-preview:generateContent?key=${keyContent}`, {
                            method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload)
                        });
                        
                        const data = await response.json();
                        if(data.error) throw new Error(data.error.message);
                        
                        const replyText = data.candidates[0].content.parts[0].text;
                        if(!currentState.settings.meggyHistory) currentState.settings.meggyHistory = [];
                        currentState.settings.meggyHistory.push({ role: "user", parts: [{ text: text }] }, { role: "model", parts: [{ text: replyText }] });
                        
                        if(currentState.settings.meggyHistory.length > 20) currentState.settings.meggyHistory = currentState.settings.meggyHistory.slice(-20);
                        await saveToDB(null); 
                        drawChat();
                    } catch (error) {
                        new Notice("🛑 Meggy Pro Hatası: " + error.message, 6000);
                        console.error("API Hatası Detayı:", error);
                    } finally {
                        sendBtn.innerText = "✨ EMRET"; sendBtn.disabled = false; promptInp.value = ""; promptInp.focus();
                    }
                };

                sendBtn.onclick = () => { let v = promptInp.value.trim(); if(v) callMeggy(v); };
                promptInp.onkeydown = (e) => { e.stopPropagation(); if(e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendBtn.click(); } };
