                charCard.onmouseover = () => { charCard.style.borderColor = char.isDead ? "#8b0000" : "#a882ff"; charCard.style.transform = "scale(1.03)"; charCard.style.boxShadow = char.isDead ? "0 15px 30px rgba(139,0,0,0.4)" : "0 15px 30px rgba(126,87,255,0.4)"; };
                charCard.onmouseout = () => { charCard.style.borderColor = "#444"; charCard.style.transform = "scale(1)"; charCard.style.boxShadow = "0 10px 20px rgba(0,0,0,0.5)"; };

