                charCard.onmouseenter = () => { charCard.querySelector(".avatar-click").style.opacity = "1"; if(silinebilir) charCard.querySelector(".del-btn").style.opacity = "1"; };
                charCard.onmouseleave = () => { charCard.querySelector(".avatar-click").style.opacity = "0"; if(silinebilir) charCard.querySelector(".del-btn").style.opacity = "0"; };
                applyCharacterVisualState(charCard,char,{imageSelector:".avatar-surface"});
                charCard.querySelector(".avatar-click").onclick = (e) => { e.stopPropagation(); showCustomImagePicker("avatar", async (path) => { char.avatar = path || ""; char.image = char.avatar; await saveToDB("🖼️ Suretin silüeti mühürlendi."); renderGrid(); }, {bucket:"Characters"}); };
                if(silinebilir) { charCard.querySelector(".del-btn").onclick = (e) => { e.stopPropagation(); showDeleteModal(char); }; }
                charCard.onclick = () => openCharacterMenu(char, charCard.innerHTML, deadFilter);
                
                gridContainer.appendChild(charCard);
