                const newChar = { id: Date.now(), isMain: isMainNew, name: genName(2, 4), surname: genName(2, 3), race: initialRace, raceMode: "alekrythae", alekrythaeRace: initialRace, outerRealmRace: "", melezRaces: [], health: { current: 24, maximum: 24 }, arcanaReserve: { current: 240, maximum: 240 }, isUnconscious: false, gender: p(["Erkek", "Kadın", "Cinsiyetsiz"]), title: "Yeni Uyanan", avatar: "", isLocked: false, isDead: false, envanter: [], skillTree: JSON.parse(JSON.stringify(defaultSkillTree)), journal: [], quests: [], sheet: "" };
                ensureAlekrythaSpeciesBinding(newChar);
                currentState.characters.push(newChar);
                await saveToDB("✨ Evrene yeni bir beden düştü.", `> [!info] 👥 **YENİ RUH:** ${newChar.name} evrene dahil oldu.`);
                renderGrid();
