const ADVENTURE_VIEW_IDS = new Set(["ai","calendar","reverie","map","connections","lore","performer"]);
function captureAdventureUiState(){
    if(!activeAdventure||!storyData)return;
    const game=normalizeGameRuntime(),previous=game.ui&&typeof game.ui==="object"?game.ui:{};
    game.ui={
        ...previous,
        activeView:ADVENTURE_VIEW_IDS.has(activeV2View)?activeV2View:"calendar",
        journeyContainerKey:String(currentJourneyContainerKey||"root"),
        selectedLoreKey:String(selectedLoreKey||""),
        loreScroll:{nav:Math.max(0,Number(loreScrollState?.nav)||0),reader:Math.max(0,Number(loreScrollState?.reader)||0)},
        activeReverieId:String(activeReverieId||""),
        mapMode:String(mapMode||"select"),
        updatedAt:new Date().toISOString()
    };
    storyData.lore.selectedKey=selectedLoreKey||null;
    storyData.lore.search=String(storyData.lore.search||"");
    storyData.lore.collapsed=storyData.lore.collapsed&&typeof storyData.lore.collapsed==="object"?storyData.lore.collapsed:{};
}
function restoreAdventureUiState(){
    const ui=normalizeGameRuntime().ui&&typeof normalizeGameRuntime().ui==="object"?normalizeGameRuntime().ui:{};
    activeV2View=ADVENTURE_VIEW_IDS.has(ui.activeView)?ui.activeView:"calendar";
    currentJourneyContainerKey=isValidContainerKey(ui.journeyContainerKey)?String(ui.journeyContainerKey):"root";
    currentJourneyLocationId=currentJourneyContainerKey.startsWith("location:")?currentJourneyContainerKey.slice("location:".length):null;
    selectedLoreKey=String(ui.selectedLoreKey||storyData.lore.selectedKey||"")||firstLoreKey?.()||null;
    loreScrollState={nav:Math.max(0,Number(ui.loreScroll?.nav)||0),reader:Math.max(0,Number(ui.loreScroll?.reader)||0)};
    activeReverieId=String(ui.activeReverieId||reverieData.selectedId||"")||null;
    mapMode=String(ui.mapMode||"select");
}
let safeAiBoundsObserver = null;
let safeAiWindowResizeHandler = null;
let safeAiViewGeneration = 0;

const safeAiBoundsPayload = () => {
    const contentRect = v2Content.getBoundingClientRect();
    const panelRect = mainPanel.getBoundingClientRect();
    const viewportWidth = Math.max(
        0,
        window.innerWidth || document.documentElement?.clientWidth || panelRect.right
    );
    const viewportHeight = Math.max(
        0,
        window.innerHeight || document.documentElement?.clientHeight || panelRect.bottom
    );

    // v2Shell, eski Meggy görünümünü korumak için %111,111 genişlik ve %90
    // CSS zoom kullanır. Bu düzende içerik rect'inin layout genişliğini native
    // WPF paneline doğrudan vermek sağ kenarı yaklaşık %11 taşırır. AI yüzeyini
    // zoom uygulanmayan ana Meggy çerçevesinin gerçek görsel sınırlarına bağla.
    // Native ChatGPT yüzeyi dış çerçevenin üstüne çıkmamalı. getBoundingClientRect
    // kesirli CSS/DPI değerleri döndürebildiği için içeride görünür bir emniyet
    // payı bırak ve hesaplamayı hem içerik hem ana panel kesişimine bağla.
    const frameInsetX = 8;
    const frameInsetTop = 2;
    const frameInsetBottom = 9;
    const left = Math.ceil(
        Math.max(0, contentRect.left, panelRect.left) + frameInsetX
    );
    const top = Math.ceil(
        Math.max(0, contentRect.top, panelRect.top) + frameInsetTop
    );
    const right = Math.floor(
        Math.min(viewportWidth, contentRect.right, panelRect.right) - frameInsetX
    );
    const bottom = Math.floor(
        Math.min(viewportHeight, contentRect.bottom, panelRect.bottom) - frameInsetBottom
    );

    return {
        left,
        top,
        width: Math.max(1, right - left),
        height: Math.max(1, bottom - top)
    };
};

const stopSafeAiBoundsTracking = () => {
    try { safeAiBoundsObserver?.disconnect(); } catch (_) {}
    safeAiBoundsObserver = null;
    if (safeAiWindowResizeHandler) window.removeEventListener("resize", safeAiWindowResizeHandler);
    safeAiWindowResizeHandler = null;
};

const safeAiHostIsReady = () => {
    if (activeV2View !== "ai" || !mainPanel.isConnected || !v2Content.isConnected) return false;
    if (adventureManagerShade?.isConnected) return false;
    const panelStyle = getComputedStyle(mainPanel);
    const shellStyle = getComputedStyle(v2Shell);
    if (Number.parseFloat(panelStyle.opacity || "0") < .5 ||
        Number.parseFloat(shellStyle.opacity || "0") < .5 ||
        panelStyle.pointerEvents === "none" ||
        shellStyle.pointerEvents === "none") {
        return false;
    }
    const bounds = safeAiBoundsPayload();
    return bounds.width >= 360 && bounds.height >= 260;
};

const syncSafeAiBounds = () => {
    if (!safeAiHostIsReady() || typeof window.__alekAPI !== "function") return;
    void window.__alekAPI("safeAi.bounds", { bounds: safeAiBoundsPayload() });
};
// Core, WebView2 Ctrl+tekerlek yakınlaştırması tamamlandıktan sonra güncel
// CSS sınırlarını yeniden isteyebilir. Bu yalnız Meggy'nin kendi AI yer tutucu
// geometrisini bildirir; Edge/ChatGPT sayfasına veya içeriğine erişmez.
window.__alekSyncSafeAiBounds = syncSafeAiBounds;

const startSafeAiBoundsTracking = () => {
    stopSafeAiBoundsTracking();
    safeAiWindowResizeHandler = () => requestAnimationFrame(syncSafeAiBounds);
    window.addEventListener("resize", safeAiWindowResizeHandler);
    if (typeof ResizeObserver === "function") {
        safeAiBoundsObserver = new ResizeObserver(() => requestAnimationFrame(syncSafeAiBounds));
        safeAiBoundsObserver.observe(v2Content);
        safeAiBoundsObserver.observe(v2Shell);
    }
};

const closeSafeAiView = async () => {
    safeAiViewGeneration++;
    stopSafeAiBoundsTracking();
    try { mainPanel.querySelector(".safe-ai-prep-main-overlay")?.remove(); } catch (_) {}
    if (typeof window.__alekAPI !== "function") return;
    try { await window.__alekAPI("safeAi.close", {}); } catch (_) {}
};

const renderSafeAiView = () => {
    const generation = ++safeAiViewGeneration;
    stopSafeAiBoundsTracking();
    v2Content.classList.add("safe-ai-native-host");

    const waiting = document.createElement("section");
    waiting.className = "safe-ai-fallback safe-ai-prep-main-overlay";
    waiting.innerHTML = `
        <img class="safe-ai-fallback-orb" src="https://alek-assets.local/Assets/Bluemoon.png" alt="Mavi Ay">
        <h2>Gerçek Microsoft Edge hazırlanıyor</h2>
        <p>Normal <strong>chatgpt.com</strong> sitesi, Edge'in uygulama penceresi olarak
        bu alana kenetleniyor. Meggy sayfayı, şifreni, çerezlerini veya oturumunu okuyamaz.</p>
        <small>API yoktur; mesaj gönderme ve içerik aktarma yalnızca senin elle yaptığın işlemlerle gerçekleşir.</small>
    `;
    v2Content.replaceChildren();
    try { mainPanel.querySelector(".safe-ai-prep-main-overlay")?.remove(); } catch (_) {}
    mainPanel.appendChild(waiting);

    requestAnimationFrame(async () => {
        // Son açık görünüm AI ise uygulama yeniden başlatılırken renderV2, Mavi Ay
        // ve macera geçidi henüz tamamlanmadan çalışabilir. Bu aşamada bağımsız
        // Edge penceresini açmak Meggy'nin görünmez açılış katmanının üstüne
        // çıkmasına neden olur. Geçit tamamlanınca renderSafeAiView yeniden
        // çağrılır ve yalnız kararlı, görünür çalışma alanı burada açılır.
        if (generation !== safeAiViewGeneration ||
            activeV2View !== "ai" ||
            !safeAiHostIsReady()) {
            return;
        }

        if (typeof window.__alekAPI !== "function") {
            waiting.classList.add("error");
            waiting.querySelector("h2").textContent = "AI için güncel Ałek’ryŧhæ Core gerekli";
            waiting.querySelector("p").textContent = "Meggy dosya köprüsü bulunamadı.";
            return;
        }

        await new Promise(resolve =>
            requestAnimationFrame(() => requestAnimationFrame(resolve)));
        if (generation !== safeAiViewGeneration ||
            activeV2View !== "ai" ||
            !safeAiHostIsReady()) {
            return;
        }

        const result = await window.__alekAPI("safeAi.open", {
            bounds: safeAiBoundsPayload()
        });

        if (generation !== safeAiViewGeneration || activeV2View !== "ai") {
            try { await window.__alekAPI("safeAi.close", {}); } catch (_) {}
            return;
        }

        if (!result?.ok) {
            waiting.classList.add("error");
            waiting.querySelector("h2").textContent = "Microsoft Edge AI alanı açılamadı";
            waiting.querySelector("p").textContent =
                result?.error === "unknown_op"
                    ? "Bu Meggy revizyonu için paketteki AI uyumlu Core sürümünü kur."
                    : `Core yanıtı: ${result?.error || "unknown error"}`;
            return;
        }

        try { waiting.remove(); } catch (_) {}
        startSafeAiBoundsTracking();
        syncSafeAiBounds();
    });
};

const settleAdventureInterfaceVisibility = () => {
    if (adventureManagerShade?.isConnected) return;
    [v2Shell, v9Masthead, v2Nav, v2Content].forEach(node => {
        node.getAnimations?.().forEach(animation => animation.cancel());
        node.style.opacity = "1";
        node.style.filter = "none";
        node.style.transform = "none";
    });
    v2Shell.style.pointerEvents = "auto";
};

// Karakter ayrıntısı dokunulmaz ana şablondur.
// Diğer kartlar aynı ekrana yalnız tür davranışı kadar küçük farklarla girer.
const __alekUnifiedDetailContext=new WeakMap();
const __alekUnifiedDetailBackStack=[];
let __alekUnifiedActiveRecord=null;
const unifiedDetailRecordOf=entity=>entity&&typeof entity==="object"?(__alekUnifiedDetailContext.get(entity)?.record||null):null;
const rememberUnifiedDetailContext=(entity,record)=>{
    if(entity&&typeof entity==="object"&&record)__alekUnifiedDetailContext.set(entity,{record});
    return entity;
};
const openUnifiedEntityDetail=(record,{pushCurrent=true,initialTab=null}={})=>{
    if(!record?.entity)return;
    if(pushCurrent&&__alekUnifiedActiveRecord&&__alekUnifiedActiveRecord.key!==record.key)__alekUnifiedDetailBackStack.push(__alekUnifiedActiveRecord);
    const entity=ensureFunctionalEntityFields(record.entity,record.type);
    if(initialTab){const ui=getCharacterUiState(entity);ui.activeTab=String(initialTab);ui.tabScroll[String(initialTab)]=0;}
    if(record.type==="being"){entity.__being=true;entity.entityType="being";}
    if(record.type==="location"||record.type==="realm"||record.type==="land")entity.__location=true;
    if(record.type==="mount"){entity.__mount=true;entity.isMount=true;}
    if(record.type==="group"){entity.__group=true;entity.isGroup=true;}
    __alekUnifiedActiveRecord=record;
    rememberUnifiedDetailContext(entity,record);
    openLegacyCharacter(entity);
};

const snapshotJourneyHierarchy=()=>{try{return new Map(allJourneyEntityRecords().map(item=>[item.key,{containerKey:String(item.entity.containerKey||"root"),containerSection:String(item.entity.containerSection||item.type||"")}]))}catch(_){return new Map();}};
const restoreJourneyHierarchy=snapshot=>{if(!(snapshot instanceof Map)||!snapshot.size)return;for(const [key,state] of snapshot){const record=entityFromSpatialKey(key);if(!record)continue;record.entity.containerKey=state.containerKey;record.entity.containerSection=state.containerSection;}};
const closeLegacyCharacter = (options={}) => {
    const useHistory=options?.useHistory!==false;
    const hierarchySnapshot=!useHistory?snapshotJourneyHierarchy():null;
    if(useHistory&&__alekUnifiedDetailBackStack.length){
        const previous=__alekUnifiedDetailBackStack.pop();
        __alekUnifiedActiveRecord=null;
        openUnifiedEntityDetail(previous,{pushCurrent:false});
        return;
    }
    // ESC kağıt geçmişinde yürümez. Ayrıntıyı tamamen kapatır ve
    // Journey'deki ana kart görünümüne döner; geçmiş yalnız Alt + E içindir.
    if(!useHistory)__alekUnifiedDetailBackStack.length=0;
    __alekUnifiedActiveRecord=null;
    destroyCharacterVitals(detailPanel);
    destroyArcanaReserve(detailPanel);
    destroyStamina(detailPanel);
    destroyMetanet(detailPanel);
    try{ detailPanel.__layoutCleanup?.(); }catch(_){ }
    detailPanel.__layoutCleanup = null;
    const activeAvatar = document.getElementById("activeAvatar");
    if (activeAvatar) activeAvatar.remove();
    mainPanel.classList.remove("character-detail-open","character-detail-compact");
    detailPanel.style.right = "-100%";
    detailPanel.style.left = "";
    detailPanel.style.width = "70%";
    detailPanel.style.padding = "0 40px 14px clamp(136px, 13.5%, 170px)";
    detailPanel.style.display = "none";
    detailPanel.innerHTML = "";
    gridContainer.style.display = "none";
    topBarContainer.style.display = "none";
    v2Shell.style.display = "flex";
    if(hierarchySnapshot?.size)restoreJourneyHierarchy(hierarchySnapshot);
    const returnContext=window.__ALEK_RETURN_TO_JOA_AFTER_SHEET__;
    const returnToJoA=!!returnContext;
    if(returnToJoA){
        // Kart, Mevcudat ve Map birbirinden bağımsız sayfalardır. Karttan ESC
        // ile çıkarken harita renderer'ı, canvas veya chunk üretimi bir kare
        // bile başlatılmaz; doğrudan bağımsız Mevcudat yüzeyi açılır.
        activeV2View="journey";
        try{delete window.__ALEK_RETURN_TO_JOA_AFTER_SHEET__;}catch(_){window.__ALEK_RETURN_TO_JOA_AFTER_SHEET__=null;}
        queueMicrotask(()=>{
            try{window.__alekOpenJoAInventoryPage?.();}
            catch(error){console.warn("Bağımsız JoA Mevcudat açılamadı",error);}
        });
        return;
    }
    renderV2(activeV2View);
};

const openLegacyCharacter = char => {
    try{detailPanel.__deadReadonlyCleanup?.();}catch(_){ }
    detailPanel.__deadReadonlyCleanup=null;
    destroyCharacterVitals(detailPanel);
    destroyArcanaReserve(detailPanel);
    destroyStamina(detailPanel);
    destroyMetanet(detailPanel);
    try{ detailPanel.__layoutCleanup?.(); }catch(_){ }
    detailPanel.__layoutCleanup = null;
    document.getElementById("activeAvatar")?.remove();

    // Kanonik karakter ayrıntısı yeniden açılırken eski DOM ve etkileşim kilitleri taşınmaz.
    detailPanel.innerHTML = "";
    detailPanel.hidden = false;
    detailPanel.inert = false;
    detailPanel.style.pointerEvents = "auto";
    detailPanel.style.display = "flex";
    detailPanel.style.right = "-100%";
    mainPanel.classList.remove("character-detail-open","character-detail-compact");
    v2Shell.style.display = "none";
    gridContainer.style.display = "none";
    topBarContainer.style.display = "none";

    try {
        const incomingRecord=unifiedDetailRecordOf(char);
        const nativeIdentity=!incomingRecord||incomingRecord.type==="character"||incomingRecord.type==="being"||incomingRecord.type==="mount";
        if(nativeIdentity){
            ensureCharacterFlags(char);
            ensureEntitySheetFields(char,char?.__location?"location":"character");
        }else{
            ensureNarrativeCardFields(char);
            if(isInstitutionEntityType(incomingRecord.type))ensureInstitutionResources(char);
            if(incomingRecord.type==="group")normalizeGroup(char);
        }
        openCharacterMenu(char, "", char.isDead ? "filter:grayscale(1);" : "");
        requestAnimationFrame(() => {
            const back = detailPanel.querySelector("#geriBtn");
            if (back) back.onclick = () => closeLegacyCharacter({useHistory:false});
            detailPanel.querySelectorAll("button,input,select,textarea,label,summary").forEach(node => {
                node.style.pointerEvents = "auto";
            });
        });
    } catch (openError) {
        console.error("Karakter ayrıntısı açılamadı:",openError);
        document.getElementById("activeAvatar")?.remove();
        mainPanel.classList.remove("character-detail-open","character-detail-compact");
        detailPanel.style.display = "none";
        detailPanel.innerHTML = "";
        v2Shell.style.display = "flex";
        try{delete window.__ALEK_RETURN_TO_JOA_AFTER_SHEET__;}catch(_){window.__ALEK_RETURN_TO_JOA_AFTER_SHEET__=null;}
        renderV2(activeV2View);
        new Notice("🛑 Karakter ayrıntısı açılamadı: "+(openError?.message||openError),8000);
    }
};

const setActiveNavStyle = () => {
    v2Nav.querySelectorAll("button").forEach(btn => btn.classList.toggle("active", btn.dataset.view === activeV2View));
};

const renderV2 = async view => {
    const requestedRaw=view||activeV2View;
    const requestedView=ADVENTURE_VIEW_IDS.has(requestedRaw)?requestedRaw:"calendar";
    const previousView=activeV2View;
    const viewChanged=requestedView!==activeV2View;
    if(previousView==="ai"&&requestedView!=="ai")await closeSafeAiView();
    disposeViewRuntime(previousView);
    activeV2View = requestedView;
    activeConnectionWorkspace = null;
    activeMapWorkspace = null;
    if (ALEK_MEDIA_CHANNEL_IDS.includes(activeV2View)) activateMediaTarget(activeV2View, { persist: false });
    v2Shell.dataset.realm = activeV2View;
    const v9Label = v9Masthead.querySelector(".v9-view-label");
    if (v9Label) v9Label.textContent = v9ViewTitles[activeV2View] || "Ałek’ryŧhæ";
    const adventureChip=v9Masthead.querySelector(".v9-active-adventure");
    if(adventureChip){
        adventureChip.style.setProperty("display","block","important");
        const activeName=activeAdventure?.name||DEFAULT_ADVENTURE_NAME;
        adventureChip.textContent=activeName;
        adventureChip.title=`${activeName} · ${formatGameTime()}`;
        adventureChip.dataset.adventureName=activeName;
    }
    setActiveNavStyle();
    v2Content.classList.toggle("safe-ai-native-host",activeV2View==="ai");
    v2Content.classList.remove("alek-notes-mode");
    v2Content.classList.remove("v9-view-enter");
    v2Content.replaceChildren();
    if (activeV2View === "ai") renderSafeAiView();
    else if (activeV2View === "calendar") { syncCalendarFromGameTime(); renderFantasyCalendar(); }
    else if (activeV2View === "reverie") renderReverie();
    else if (activeV2View === "map") renderMap();
    else if (activeV2View === "connections") renderConnections();
    else if (activeV2View === "lore") renderLore();
    else renderPerformer();
    void v2Content.offsetWidth;
    v2Content.classList.add("v9-view-enter");
    v2Content.dataset.alekRuntimeScope="active-view";
    window.dispatchEvent(new CustomEvent("alek:view-changed",{detail:{view:activeV2View,previousView}}));
    window.__ALEK_RESOURCE_GOVERNOR__?.wake?.(v2Content);
    alekWakeResourceBars(v2Content,8);
    if(normalizeGameRuntime().mode==="real_world")__runRealWorldClock?.();
    if(viewChanged&&activeAdventure){captureAdventureUiState();scheduleAutoSave(null,120);}
};
v2Nav.querySelectorAll("button[data-view]").forEach(btn => btn.onclick = () => renderV2(btn.dataset.view));


const insertEmojiIntoTarget = (emoji) => {
    const target = activeEmojiTarget;
    if (!target) { new Notice("Önce bir yazı alanına tıkla."); return; }
    if (target.isContentEditable) {
        target.focus();
        try { document.execCommand("insertText", false, emoji); } catch (_) { target.textContent += emoji; }
        target.dispatchEvent(new Event("input", {bubbles:true}));
        return;
    }
    if (!(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement)) return;
    const start = Number.isFinite(target.selectionStart) ? target.selectionStart : target.value.length;
    const end = Number.isFinite(target.selectionEnd) ? target.selectionEnd : start;
    target.value = target.value.slice(0,start) + emoji + target.value.slice(end);
    const cursor = start + emoji.length;
    target.focus(); target.setSelectionRange(cursor,cursor);
    target.dispatchEvent(new Event("input", {bubbles:true}));
};

document.addEventListener("focusin", e => {
    const t=e.target;
    if (t && (t.matches?.("input,textarea") || t.isContentEditable)) activeEmojiTarget=t;
}, true);

const closeEmojiKeyboard = async () => {
    if (emojiKeyboardPanel) emojiKeyboardPanel.remove();
    emojiKeyboardPanel=null;
    storyData.settings.emojiKeyboard.open=false;
    scheduleAutoSave(null,120);
};
const openEmojiKeyboard = () => {
    if (emojiKeyboardPanel) { closeEmojiKeyboard(); return; }
    const state=storyData.settings.emojiKeyboard;
    const panel=document.createElement("div");panel.className="alek-emoji-keyboard";
    panel.style.left=`${Number(state.x)||40}px`;panel.style.top=`${Number(state.y)||90}px`;
    const head=document.createElement("div");head.className="emoji-keyboard-head";
    const label=document.createElement("strong");label.textContent="A̤ɐ͜ɨǣ́ꞎ͡ƣ İmge Paleti";
    const close=document.createElement("button");close.textContent="×";head.append(label,close);
    const tabs=document.createElement("div");tabs.className="image-palette-tabs";
    const paletteModes=[
        {id:"images",label:"İmgeler",items:()=>ALEK_IMAGE_PALETTE},
        {id:"alphabet",label:"240 Harf",items:()=>ALEK_ALPHABET_240},
        {id:"meaning-weave",label:"24 Anlam-Örgü",items:()=>ALEK_MEANING_WEAVE_24},
        {id:"resonance",label:"24 Rezonans",items:()=>ALEK_RESONANCE_24}
    ];
    if(!paletteModes.some(mode=>mode.id===state.tab)) state.tab="images";
    const tabButtons=new Map();
    paletteModes.forEach(mode=>{
        const button=document.createElement("button");
        button.type="button";button.textContent=mode.label;button.dataset.paletteTab=mode.id;
        button.onclick=()=>{state.tab=mode.id;draw();scheduleAutoSave(null,100);};
        tabs.appendChild(button);tabButtons.set(mode.id,button);
    });
    const grid=document.createElement("div");grid.className="emoji-keyboard-grid";
    const draw=()=>{
        const mode=paletteModes.find(item=>item.id===state.tab)||paletteModes[0];
        tabButtons.forEach((button,id)=>button.classList.toggle("active",id===mode.id));
        grid.className=`emoji-keyboard-grid palette-${mode.id}`;
        grid.innerHTML="";
        mode.items().forEach(item=>{
            const entry=typeof item==="string"?{display:item,insert:item,name:"",description:""}:item;
            const b=document.createElement("button");b.type="button";
            if(entry.name){
                b.classList.add("named-palette-symbol");
                const symbol=document.createElement("span");symbol.className="palette-symbol";symbol.textContent=entry.display;
                const name=document.createElement("small");name.textContent=entry.name;
                b.append(symbol,name);
            } else b.textContent=entry.display;
            b.title=entry.name?`${entry.name} · ${entry.description}`:(mode.id==="alphabet"?`Aktarım harfi: ${entry.display}`:entry.display);
            b.setAttribute("aria-label",entry.name||entry.display);
            b.onclick=()=>insertEmojiIntoTarget(entry.insert);
            grid.appendChild(b);
        });
    };
    panel.append(head,tabs,grid);mainPanel.appendChild(panel);emojiKeyboardPanel=panel;state.open=true;draw();scheduleAutoSave(null,100);
    let drag=null;
    head.addEventListener("pointerdown",e=>{if(e.target===close||e.button!==0)return;drag={x:e.clientX,y:e.clientY,left:panel.offsetLeft,top:panel.offsetTop};try{head.setPointerCapture(e.pointerId);}catch(_){}});
    head.addEventListener("pointermove",e=>{if(!drag)return;const left=drag.left+e.clientX-drag.x,top=drag.top+e.clientY-drag.y;panel.style.left=`${left}px`;panel.style.top=`${top}px`;state.x=left;state.y=top;});
    head.addEventListener("pointerup",e=>{if(!drag)return;drag=null;try{head.releasePointerCapture(e.pointerId);}catch(_){}scheduleAutoSave(null,120);});
    close.onclick=closeEmojiKeyboard;
};
v2Nav.querySelector('[data-action="emoji-keyboard"]').onclick=openEmojiKeyboard;

const navMapLibraryButton=v2Nav.querySelector('[data-action="map-library"]');if(navMapLibraryButton)navMapLibraryButton.onclick=()=>openMapLibraryPalette(async item=>{await applySelectedMapLibraryItem(item,true);new Notice(`${item.name} seçildi. Cartographer’s Table üzerinde F ile yerleştir.`);});
