const showV2Modal = ({title, body, onSave, saveText="Kaydet", wide=false, dangerText=""}) => {
    const shade = document.createElement("div");
    shade.className = "alek-v2-modal-shade";
    const box = document.createElement("div");
    box.className = "alek-v2-modal" + (wide ? " wide" : "");
    const titleEl = document.createElement("h3"); titleEl.textContent = title;
    const bodyEl = document.createElement("div"); bodyEl.className = "alek-v2-modal-body";
    if (typeof body === "string") bodyEl.textContent = body; else bodyEl.appendChild(body);
    const actions = document.createElement("div"); actions.className = "alek-v2-modal-actions";
    const cancel = document.createElement("button"); cancel.textContent = "İptal";
    if (dangerText) {
        const danger = document.createElement("button");
        danger.textContent = dangerText;
        danger.className = "danger";
        actions.appendChild(danger);
        bodyEl.__dangerButton = danger;
    }
    const save = document.createElement("button"); save.textContent = saveText; save.className = "primary";
    actions.append(cancel, save); box.append(titleEl, bodyEl, actions); shade.appendChild(box); mainPanel.appendChild(shade);
    cancel.onclick = () => shade.remove();
    shade.onclick = e => { if(e.target === shade) shade.remove(); };
    save.onclick = async () => { if(onSave) { const result = await onSave(bodyEl, shade); if(result === false) return; } shade.remove(); };
    return {shade, box, body:bodyEl, save, danger:bodyEl.__dangerButton};
};

// Sürümden bağımsız veri taşıma kasası.
// Dışa aktarım önce açık macerayı diske yazar. İçe aktarım süresince otomatik
// kayıt kilitlenir; Core eski veriyi uyarlayıp mevcut verinin ön yedeğini alır.
