    ensureV4Data();const root=document.createElement("section");root.className="reverie-root";const toolbar=document.createElement("header");toolbar.className="reverie-toolbar";const heading=document.createElement("div");heading.innerHTML='<small>HİKÂYE MÜHÜRLERİ</small><h2>Reverie</h2><p>Anlatıları kartlar hâlinde sakla, mühürle ve yeniden aç.</p>';const add=document.createElement("button");add.className="primary";add.textContent="＋ Yeni Hikâye";add.onclick=createReverieEntry;toolbar.append(heading,add);root.appendChild(toolbar);
