const appendReverieTextFlow=(editor,value)=>{
    const text=String(value??"").replace(/\r/g,"");
    if(!text)return;
    const parts=text.split("\n");
    parts.forEach((part,index)=>{
        if(part)editor.appendChild(document.createTextNode(part));
        if(index<parts.length-1)editor.appendChild(document.createElement("br"));
    });
};
const renderReverieStoryBlocks=(editor,blocks,onMutation,{readOnly=false}={})=>{
    editor.innerHTML="";
    let count=0;
    const list=Array.isArray(blocks)?blocks:[];
    list.forEach((block,index)=>{
        if(block?.type==="image"&&block.path){
            editor.appendChild(createReverieStoryImageBlock(block.path,"Reverie görseli",onMutation,{widthPct:block.widthPct,align:block.align,readOnly}));
            count++;
            const next=list[index+1];
            if(!readOnly&&(!next||next?.type==="image"))editor.appendChild(createReverieStoryTextBlock(""));
            return;
        }
        if(block?.type==="text"){
            appendReverieTextFlow(editor,block.text);
            count++;
        }
    });
    if(!count&&!readOnly)editor.innerHTML="";
};
const collectReverieStoryBlocks=editor=>{
    const blocks=[];let buffer="";
    const flush=()=>{
        const value=buffer.replace(/\u00a0/g," ").replace(/\r/g,"");
        if(value)blocks.push({type:"text",text:value});
        buffer="";
    };
    const walk=node=>{
        if(node.nodeType===Node.TEXT_NODE){buffer+=node.nodeValue||"";return;}
        if(node.nodeType!==Node.ELEMENT_NODE)return;
        const element=node;
        if(element.matches("figure[data-reverie-image]")){
            flush();
            const path=String(element.dataset.reverieImage||element.querySelector("img")?.dataset?.sourcePath||"").trim();
            if(path)blocks.push({
                type:"image",
                path,
                widthPct:clamp(Number(element.dataset.reverieWidth)||100,20,100),
                align:["left","center","right"].includes(element.dataset.reverieAlign)?element.dataset.reverieAlign:"center"
            });
            return;
        }
        if(element.tagName==="BR"){buffer+="\n";return;}
        const blockLike=/^(P|DIV|LI|H[1-6]|BLOCKQUOTE)$/.test(element.tagName);
        Array.from(element.childNodes).forEach(walk);
        if(blockLike)flush();
    };
    Array.from(editor.childNodes).forEach(walk);
    flush();
    while(blocks.length&&blocks[0].type==="text"&&!blocks[0].text.trim())blocks.shift();
    while(blocks.length&&blocks[blocks.length-1].type==="text"&&!blocks[blocks.length-1].text.trim())blocks.pop();
    return blocks;
};
const placeReverieCaret=(editor,node,atStart=true)=>{
    editor.focus();const selection=window.getSelection(),range=document.createRange();range.selectNodeContents(node||editor);range.collapse(!!atStart);selection.removeAllRanges();selection.addRange(range);
};
const ensureReverieAfterImageBlock=editor=>{
    const children=Array.from(editor.childNodes);
    const lastFigure=[...children].reverse().find(node=>node.nodeType===Node.ELEMENT_NODE&&node.matches?.("figure[data-reverie-image]"));
    if(!lastFigure)return null;
    let node=lastFigure.nextSibling;
    while(node&&node.nodeType===Node.TEXT_NODE&&!String(node.nodeValue||"").trim())node=node.nextSibling;
    if(node?.nodeType===Node.ELEMENT_NODE&&node.matches?.(".reverie-story-text-block"))return node;
    if(node)return null;
    const tail=createReverieStoryTextBlock("");
    lastFigure.after(tail);
    return tail;
};
const placeReverieCaretAfterNode=(editor,node)=>{
    if(!node)return placeReverieCaret(editor,editor,false);
    editor.focus();const selection=window.getSelection(),range=document.createRange();range.setStartAfter(node);range.collapse(true);selection.removeAllRanges();selection.addRange(range);
};
const insertReverieStoryImage=(editor,path,savedRange,onMutation)=>{
    const figure=createReverieStoryImageBlock(path,"Hikâye içi görsel",onMutation,{widthPct:45,align:"center",readOnly:false});
    const after=createReverieStoryTextBlock("");
    let range=savedRange;
    if(!range||!editor.contains(range.commonAncestorContainer)){
        range=document.createRange();range.selectNodeContents(editor);range.collapse(false);
    }
    let startNode=range.startContainer.nodeType===Node.ELEMENT_NODE?range.startContainer:range.startContainer.parentElement;
    let block=startNode;
    while(block&&block.parentElement!==editor)block=block.parentElement;
    if(block&&block!==editor&&!block.matches("figure[data-reverie-image]")){
        let offset=0;
        try{const pre=range.cloneRange();pre.selectNodeContents(block);pre.setEnd(range.startContainer,range.startOffset);offset=pre.toString().length;}catch(_){ }
        const full=String(block.innerText||block.textContent||"").replace(/\r/g,"");
        const beforeText=full.slice(0,offset),afterText=full.slice(offset);
        const fragment=document.createDocumentFragment();
        if(beforeText)fragment.appendChild(createReverieStoryTextBlock(beforeText));
        fragment.appendChild(figure);
        const tail=createReverieStoryTextBlock(afterText);
        fragment.appendChild(tail);
        block.replaceWith(fragment);
        placeReverieCaret(editor,tail,true);
    }else{
        try{range.insertNode(figure);figure.after(after);}catch(_){editor.append(figure,after);}
        placeReverieCaret(editor,after,true);
    }
    onMutation?.();
};
