    configureAdventurePaths(adventure);await seedAdventureFolder(adventure,{migrateLegacy:false});await writeAdventureRegistry();
    storyData=normalizeStoryRuntimeData(await readJsonSafe(DATA_PATHS.journey,defaultStoryData));
    characterData=await readJsonSafe(DATA_PATHS.characters,defaultCharacterData);
    locationData=await readJsonSafe(DATA_PATHS.locations,defaultLocationData);
    groupData=await readJsonSafe(DATA_PATHS.groups,defaultGroupData);
