    const input=document.createElement("input"),hint=document.createElement("small");input.placeholder="Çalışma alanı adı";input.maxLength=120;hint.textContent="Her çalışma alanı kendi Games/<ad>/game.db dosyasında tutulur ve gerçek dünya tarih/saatini kullanır.";
