function alekResourceBarLayers(kind){
    const normalized=alekNormalizeResourceBarKind(kind),raw=__alekResourceBarIndex?.[normalized]||__alekResourceBarIndex?.[normalized[0].toUpperCase()+normalized.slice(1)]||__alekResourceBarFallback[normalized]||[];
    return Array.from(raw).map((layer,index)=>({
        relativePath:String(layer.relativePath??layer.RelativePath??""),
        opacity:Math.max(0,Math.min(1,Number(layer.opacity??layer.Opacity??((Number(layer.opacityPercent??layer.OpacityPercent)||100)/100)))),
        durationSeconds:Math.max(.1,Number(layer.durationSeconds??layer.DurationSeconds)||12),
        index
    })).filter(layer=>layer.relativePath).sort((a,b)=>b.opacity-a.opacity||b.durationSeconds-a.durationSeconds);
}
function energyFlowSvg(kind,orientation="horizontal"){
    const normalized=alekNormalizeResourceBarKind(kind);
    return `<span class="energy-flow ef-${normalized}" data-kind="${normalized}" data-orientation="${orientation}" aria-hidden="true"><canvas class="energy-flow-canvas" data-kind="${normalized}" data-orientation="${orientation}"></canvas></span>`;
}
function alekMountBarFlow(track){
    if(!track)return;alekEnsureEnergyFlowStyle();
    const flows=()=>Array.from(track.querySelectorAll(".energy-flow"));
    const setW=()=>{
        const w=track.clientWidth,h=track.clientHeight;
        if(w)track.style.setProperty("--track-w",w+"px");
        if(h)track.style.setProperty("--track-h",h+"px");
    };
    const hasRenderableFill=()=>flows().some(flow=>{
        const host=flow.parentElement||flow;
        const rect=host.getBoundingClientRect();
        if(rect.width<=1||rect.height<=1)return false;
        const style=getComputedStyle(host);
        return style.display!=="none"&&style.visibility!=="hidden"&&Number(style.opacity||1)>0;
    });
    const controllers=[];
    const mountCanvases=()=>flows().forEach(flow=>{
        const canvas=flow.querySelector(".energy-flow-canvas");if(!canvas||canvas.__alekResourceController)return;
        const kind=alekNormalizeResourceBarKind(flow.dataset.kind||canvas.dataset.kind||"aia");
        const layers=alekResourceBarLayers(kind).map(layer=>({url:getDynamicUrl(`Assets/resource-bars/${layer.relativePath}`),opacity:layer.opacity,duration:layer.durationSeconds}));
        const controller=window.__ALEK_RENDERER__?.mountResourceFlow(canvas,{layers,orientation:flow.dataset.orientation||canvas.dataset.orientation||"horizontal"});
        if(controller){canvas.__alekResourceController=controller;controllers.push(controller);}
    });
    const sync=()=>{
        // IntersectionObserver yalnız yeniden ölçüm tetikler. Aç/kapa kararı
        // doğrudan güncel ekran geometrisinden verilir; gecikmiş observer olayı
        // görünür barı söndürüp tekrar yakamaz.
        const active=alekResourceTrackIsVisible(track)&&alekResourceAppCanAnimate()&&hasRenderableFill();
        track.__alekResourceActive=active;
        track.classList.toggle("resource-flow-active",active);
        track.classList.toggle("flow-off",!active);
        mountCanvases();controllers.forEach(controller=>controller.setActive(active));
    };
    let syncRaf=0;
    const queueSync=()=>{if(syncRaf)return;syncRaf=requestAnimationFrame(()=>{syncRaf=0;setW();sync();});};
    setW();
    track.__alekSyncResourceFlow=queueSync;
    __alekMountedResourceTracks.add(track);
    if(track.__efMounted){queueSync();return;}
    track.__efMounted=true;
    const isInitiallyVisible=()=>alekResourceTrackIsVisible(track);
    let ro=null;
    try{
        ro=new ResizeObserver(queueSync);
        ro.observe(track);
        flows().forEach(flow=>{if(flow.parentElement)ro.observe(flow.parentElement)});
    }catch(_){window.addEventListener("resize",queueSync,{passive:true})}
    let io=null;
    if("IntersectionObserver" in window){
        try{
            io=new IntersectionObserver(()=>queueSync(),{rootMargin:"32px",threshold:0});
            io.observe(track);
        }catch(_){queueSync()}
    }
    queueSync();
    let settleRaf=0,settleFrames=120,visibleFrames=0,cleaned=false;
    const settleOpeningLayout=()=>{
        settleRaf=0;
        if(cleaned||!track.isConnected)return;
        if(!alekResourceAppCanAnimate())return;
        visibleFrames=isInitiallyVisible()?visibleFrames+1:0;
        queueSync();controllers.forEach(controller=>controller.prime?.()||controller.invalidate?.());
        if(--settleFrames>0&&visibleFrames<8)settleRaf=requestAnimationFrame(settleOpeningLayout);
    };
    const onLayoutFinished=()=>{queueSync();controllers.forEach(controller=>controller.prime?.()||controller.invalidate?.());};
    track.addEventListener("animationend",onLayoutFinished,true);
    track.addEventListener("transitionend",onLayoutFinished,true);
    settleRaf=requestAnimationFrame(settleOpeningLayout);
    track.__efCleanup=()=>{
        cleaned=true;
        if(syncRaf)cancelAnimationFrame(syncRaf);
        if(settleRaf)cancelAnimationFrame(settleRaf);
        try{ro?.disconnect()}catch(_){}
        try{io?.disconnect()}catch(_){}
        window.removeEventListener("resize",queueSync);
        track.removeEventListener("animationend",onLayoutFinished,true);
        track.removeEventListener("transitionend",onLayoutFinished,true);
        controllers.splice(0).forEach(controller=>controller.dispose());
        __alekMountedResourceTracks.delete(track);
        delete track.__alekSyncResourceFlow;
    };
}

// -------------------------- Journey kartı durum katmanı (BAYGIN / ÖLDÜ / ÖLÜMSÜZ) --------------------------
function alekComputeIsUnconscious(item){
    if(!item||item.isDead)return false;
    syncCharacterThresholdStates(item);
    return !!item.isUnconscious;
}
function alekCardStateFilter(item){
    if(item&&item.isDead)return "grayscale(100%) brightness(0.4) contrast(1.03)";
    if(alekComputeIsUnconscious(item))return "brightness(0.7) saturate(0.82)";
    return "";
}
function alekCardStateRibbon(item){
    if(item&&item.isDead)return '<div class="alek-state-ribbon dead"><div class="main">DEAD</div><div class="sub">Life has ended</div></div>';
    if(alekComputeIsUnconscious(item))return '<div class="alek-state-ribbon unconscious"><div class="main">UNCONSCIOUS</div><div class="sub">Life signs continue</div></div>';
    return "";
}
function alekApplyJourneyCardState(card,item){
    if(!card||!item)return;
    const unconscious=alekComputeIsUnconscious(item);
    const immortal=!!item.isImmortal;
    card.classList.toggle("is-immortal",immortal);
    card.classList.toggle("is-dead",!!item.isDead);
    card.classList.toggle("is-unconscious",unconscious&&!item.isDead);
    card.querySelectorAll(".alek-state-ribbon,.alek-immortal-chip").forEach(n=>n.remove());
    const imgWrap=card.querySelector(".journey-image");
    if(imgWrap)imgWrap.style.filter=alekCardStateFilter(item);
    if(immortal)card.insertAdjacentHTML("beforeend",'<div class="alek-immortal-chip">∞ IMMORTAL</div>');
    const rib=alekCardStateRibbon(item);
    if(rib)card.insertAdjacentHTML("beforeend",rib);
}

