// -------------------------- Adventurer · Karakter, Mekân, Grup ve Binek Külliyatı --------------------------
const entityTypeOf=(entity,type=null)=>type||entity?.entityType||(entity?.__mount||entity?.isMount?"mount":entity?.__group||entity?.isGroup?"group":entity?.__location||entity?.isLocation?"location":"character");
const entitySpatialKey=(entity,type=null)=>`${entityTypeOf(entity,type)}:${entity?.id}`;
const entityFromSpatialKey=key=>{
    const text=String(key||""),split=text.indexOf(":");if(split<1)return null;
    const type=text.slice(0,split),id=text.slice(split+1);
    if(type==="location"){const entity=getLocationById(id);return entity?{type,entity,key:text}:null;}
    if(type==="character"){const entity=getCharacterById(id);return entity?{type,entity,key:text}:null;}
    if(type==="group"){const entity=(groupData.groups||[]).find(group=>String(group.id)===String(id));return entity?{type,entity,key:text}:null;}
    if(type==="mount"){const entity=(mountData.mounts||[]).find(mount=>String(mount.id)===String(id));return entity?{type,entity,key:text}:null;}
    if(ALEK_GENERIC_ENTITY_TYPES.includes(type)){const entity=getGenericEntityById(type,id);return entity?{type,entity,key:text}:null;}
    return null;
};
const normalizedContainerKey=value=>isValidContainerKey(value)?String(value):"root";
const entityContainerKey=(entity,type=null)=>{
    const kind=entityTypeOf(entity,type);
    if(typeof entity?.containerKey==="string")return normalizedContainerKey(entity.containerKey);
    const locationId=kind==="location"?entity?.parentLocationId:entity?.locationId;
    return locationId?`location:${locationId}`:"root";
};
const containerLabel=key=>{
    if(key==="root")return"Ana Dünya";
    const record=entityFromSpatialKey(key);return record?fullNameOf(record.entity):"Bilinmeyen Katman";
};
const containerChain=key=>{
    const chain=[],seen=new Set();let current=normalizedContainerKey(key);
    while(current!=="root"&&!seen.has(current)){seen.add(current);const record=entityFromSpatialKey(current);if(!record)break;chain.unshift(record);current=entityContainerKey(record.entity,record.type);}
    return chain;
};
const containerWouldCycle=(entityKey,targetKey)=>{
    let current=normalizedContainerKey(targetKey),guard=0;
    while(current!=="root"&&guard++<256){if(current===entityKey)return true;const record=entityFromSpatialKey(current);if(!record)return false;current=entityContainerKey(record.entity,record.type);}
    return false;
};
const setEntityContainerKey=(entity,type,targetKey,{sectionId=null}={})=>{
    const ownKey=entitySpatialKey(entity,type),safeTarget=normalizedContainerKey(targetKey);
    if(ownKey===safeTarget||containerWouldCycle(ownKey,safeTarget))return false;
    entity.containerKey=safeTarget;
    entity.containerSection=sectionId?String(sectionId):String(entity.containerSection||type||"other");
    if(type==="group"||type==="mount")entity.parentGroupId=safeTarget.startsWith("group:")?safeTarget.slice("group:".length):null;
    if(type==="location")entity.parentLocationId=safeTarget.startsWith("location:")?safeTarget.slice("location:".length):null;
    if(type==="character"){
        entity.parentCharacterId=safeTarget.startsWith("character:")?safeTarget.slice("character:".length):null;
        entity.locationId=safeTarget.startsWith("location:")?safeTarget.slice("location:".length):null;
    }
    entity.updatedAt=new Date().toISOString();
    const state=storyData?.game?.journey3d,piece=state?.pieces?.[ownKey];if(piece)piece.layerKey=safeTarget;
    return true;
};
const ALEK_STABLE_SCROLL_SELECTORS=[
    ".v2-content","#v2Content",".journey-root",".journey-grid",".journey-container-sheet-scroll",
    ".character-detail-content",".character-tab-scroll",".mevcudat-tree-viewport",
    ".lore-nav",".lore-reader",".reverie-grid",".reverie-reader"
];
const captureAlekStableScroll=()=>{
    const snapshot={windowX:window.scrollX||0,windowY:window.scrollY||0,entries:[]};
    const seen=new Set();
    for(const selector of ALEK_STABLE_SCROLL_SELECTORS){
        const nodes=[...document.querySelectorAll(selector)];
        nodes.forEach((node,index)=>{
            if(!(node instanceof HTMLElement)||seen.has(node))return;
            seen.add(node);
            snapshot.entries.push({selector,index,top:node.scrollTop,left:node.scrollLeft});
        });
    }
    if(v2Content instanceof HTMLElement&&!seen.has(v2Content))snapshot.entries.push({selector:"__v2Content",index:0,top:v2Content.scrollTop,left:v2Content.scrollLeft});
    return snapshot;
};
const restoreAlekStableScroll=snapshot=>{
    if(!snapshot)return;
    const apply=()=>{
        try{window.scrollTo(snapshot.windowX||0,snapshot.windowY||0);}catch(_){}
        for(const item of snapshot.entries||[]){
            const node=item.selector==="__v2Content"?v2Content:document.querySelectorAll(item.selector)[item.index];
            if(node instanceof HTMLElement){node.scrollTop=item.top||0;node.scrollLeft=item.left||0;}
        }
    };
    requestAnimationFrame(()=>{apply();requestAnimationFrame(apply);});
};
const preserveAlekScrollDuring=async action=>{
    const snapshot=captureAlekStableScroll();
    try{return await action();}finally{restoreAlekStableScroll(snapshot);}
};
const blurWithoutScroll=node=>{try{node?.blur?.({preventScroll:true});}catch(_){try{node?.blur?.();}catch(__){}}};

const moveJourneySelectionTo = async (targetKey,{render=true,clearSelection=true,notice=true,sectionId=null,keys=null}={}) => preserveAlekScrollDuring(async()=>{
    const safeTarget=normalizedContainerKey(targetKey);
    if(safeTarget!=="root"){
        const targetRecord=entityFromSpatialKey(safeTarget);
        if(!targetRecord){new Notice("Hedef küme artık mevcut değil.");return 0;}
        if(!isContainerEntityType(targetRecord.type)){new Notice("Bu mevcudat fiziksel konteyner değildir; başka mevcudatlar buraya taşınamaz.");return 0;}
    }
    const selectedKeys=[...new Set(Array.from(keys??journeySelected).map(String))];
    let moved=0,alreadyThere=0,cycleBlocked=0,missing=0,selfBlocked=0;
    for(const key of selectedKeys){
        if(key===safeTarget){selfBlocked++;continue;}
        const record=entityFromSpatialKey(key);
        if(!record){missing++;continue;}
        const requestedSection=String(sectionId||record.type);
        if(entityContainerKey(record.entity,record.type)===safeTarget&&String(record.entity.containerSection||record.type)===requestedSection){alreadyThere++;continue;}
        if(containerWouldCycle(record.key,safeTarget)){cycleBlocked++;continue;}
        if(setEntityContainerKey(record.entity,record.type,safeTarget,{sectionId:requestedSection}))moved++;else cycleBlocked++;
    }
    if(!moved){
        if(notice){
            if(!selectedKeys.length)new Notice("Taşınacak seçili mevcudat yok.");
            else if(alreadyThere===selectedKeys.length)new Notice("Seçili mevcudatlar zaten bu kümede.");
            else if(cycleBlocked)new Notice("Yalnız gerçek bir üst-alt döngüsü oluşturan mevcudatlar taşınmadı.");
            else if(missing)new Notice("Seçili mevcudatlardan biri artık bulunamadı.");
            else if(selfBlocked)new Notice("Bir mevcudat kendi içine bırakılamaz.");
            else new Notice("Seçili mevcudatlar bu kümeye bırakılamadı.");
        }
        return 0;
    }
    if(clearSelection){selectedKeys.forEach(key=>journeySelected.delete(key));}
    await saveToDB(`${moved} mevcudat ${containerLabel(safeTarget)} / ${sectionId?entityTypeDisplayLabel(sectionId):"Mevcudat"} alt kümesine bırakıldı.`);
    if(notice)new Notice(`📥 ${moved} mevcudat · ${containerLabel(safeTarget)} › ${sectionId?entityTypeDisplayLabel(sectionId):"Mevcudat"}`);
    if(render)renderJourney();
    return moved;
});
const enterJourneyContainer=(key,{preserveSelection=false}={})=>{
    const scrollSnapshot=captureAlekStableScroll();
    const safe=normalizedContainerKey(key);
    if(safe!=="root"){
        const targetRecord=entityFromSpatialKey(safe);
        if(!targetRecord){new Notice("Bu mevcudat artık mevcut değil.");return false;}
        if(!isContainerEntityType(targetRecord.type)){new Notice("Bu mevcudat fiziksel konteyner değildir; bağlıları Bağlar ekranında görünür.");return false;}
    }
    currentJourneyContainerKey=safe;
    currentJourneyLocationId=safe.startsWith("location:")?safe.slice("location:".length):null;
    if(!preserveSelection)journeySelected.clear();
    keyEDown=false;keyWDown=false;keySDown=false;keyEIntentUntil=0;keyWIntentUntil=0;keySIntentUntil=0;
    captureAdventureUiState();scheduleAutoSave(null,100);renderJourney();restoreAlekStableScroll(scrollSnapshot);return true;
};
const openJourneyContainerInterface=(key,{preserveSelection=true}={})=>{
    const safe=normalizedContainerKey(key);
    const go=()=>enterJourneyContainer(safe,{preserveSelection});
    if(mainPanel.classList.contains("character-detail-open")){
        closeLegacyCharacter({useHistory:false});
        setTimeout(go,0);
        return true;
    }
    return go();
};
const groupDirectMembers = group => {
    const key=entitySpatialKey(group,"group");
    return [
        ...getAllCharacters().filter(item=>entityContainerKey(item,"character")===key).map(entity=>({type:"character",entity})),
        ...(locationData.locations||[]).filter(item=>entityContainerKey(item,"location")===key).map(entity=>({type:"location",entity})),
        ...(groupData.groups||[]).filter(item=>String(item.id)!==String(group.id)&&entityContainerKey(item,"group")===key).map(entity=>({type:"group",entity})),
        ...(mountData.mounts||[]).filter(item=>entityContainerKey(item,"mount")===key).map(entity=>({type:"mount",entity})),
        ...normalizeGenericEntityCards().filter(item=>entityContainerKey(item,item.entityType)===key).map(entity=>({type:entity.entityType,entity}))
    ];
};
const reparentGroupContents = (group,targetKey) => {
    const ownKey=entitySpatialKey(group,"group"),safe=normalizedContainerKey(targetKey);
    getAllCharacters().forEach(entity=>{if(entityContainerKey(entity,"character")===ownKey)setEntityContainerKey(entity,"character",safe);});
    (locationData.locations||[]).forEach(entity=>{if(entityContainerKey(entity,"location")===ownKey)setEntityContainerKey(entity,"location",safe);});
    (groupData.groups||[]).forEach(entity=>{if(String(entity.id)!==String(group.id)&&entityContainerKey(entity,"group")===ownKey)setEntityContainerKey(entity,"group",safe);});
    (mountData.mounts||[]).forEach(entity=>{if(entityContainerKey(entity,"mount")===ownKey)setEntityContainerKey(entity,"mount",safe);});
    normalizeGenericEntityCards().forEach(entity=>{if(entityContainerKey(entity,entity.entityType)===ownKey)setEntityContainerKey(entity,entity.entityType,safe);});
};
