const openGenericEntityEditor=entity=>{
    const item=normalizeGenericEntity(entity,entity?.entityType);if(!item)return;
    openUnifiedEntityDetail({type:item.entityType,entity:item,key:entitySpatialKey(item,item.entityType)},{pushCurrent:true});
};
const getJourneyDatasetForType = type => type==="character"?currentState.characters:type==="location"?locationData.locations:type==="group"?groupData.groups:type==="mount"?mountData.mounts:ALEK_GENERIC_ENTITY_TYPES.includes(type)?genericEntityCards().filter(item=>item.entityType===type):null;
const removeEntityByRecord = record => {
    if(!record)return false;const id=String(record.entity.id);
    const removedKey=`${record.type}:${id}`;
    if(record.type==="character")currentState.characters=(currentState.characters||[]).filter(item=>String(item.id)!==id);
    else if(record.type==="location")locationData.locations=(locationData.locations||[]).filter(item=>String(item.id)!==id);
    else if(record.type==="group")groupData.groups=(groupData.groups||[]).filter(item=>String(item.id)!==id);
    else if(record.type==="mount")mountData.mounts=(mountData.mounts||[]).filter(item=>String(item.id)!==id);
    else if(ALEK_GENERIC_ENTITY_TYPES.includes(record.type))normalizeGameRuntime().entityCards=genericEntityCards().filter(item=>!(item.entityType===record.type&&String(item.id)===id));
    else return false;
    if(record.type==="species"||record.type==="people"){
        const field=record.type==="species"?"speciesCardId":"peopleCardId";
        [...getAllCharacters(),...normalizeGenericEntityCards().filter(item=>item.entityType==="being")].forEach(entity=>{if(String(entity[field]||"")===id)entity[field]="";});
    }
    [...getAllCharacters(),...(locationData.locations||[]),...(groupData.groups||[]),...(mountData.mounts||[]),...normalizeGenericEntityCards()].forEach(entity=>{
        if(Array.isArray(entity.relationKeys))entity.relationKeys=entity.relationKeys.filter(key=>String(key)!==removedKey);
    });
    return true;
};
const restoreEntitySnapshot = entry => {
    const type=String(entry.type||""),snapshot=cloneData(entry.snapshot||{});if(!snapshot?.id)return false;
    const exists=entityFromSpatialKey(`${type}:${snapshot.id}`);if(exists)return true;
    if(type==="character")currentState.characters.push(normalizeLegacyCharacter(snapshot,!!snapshot.__special));
    else if(type==="location")locationData.locations.push(normalizeLocation(snapshot));
    else if(type==="group")groupData.groups.push(normalizeGroup(snapshot));
    else if(type==="mount")mountData.mounts.push(normalizeMount(snapshot));
    else if(ALEK_GENERIC_ENTITY_TYPES.includes(type)){const restored=normalizeGenericEntity(snapshot,type);if(restored)genericEntityCards().push(restored);else return false;}
    else return false;
    return true;
};
const collectJourneySubtreeKeys = roots => {
    const selected=new Set((roots||[]).map(String));let changed=true;
    while(changed){changed=false;for(const type of ["character","location","group","mount",...ALEK_GENERIC_ENTITY_TYPES]){const list=type==="character"?getAllCharacters():type==="location"?(locationData.locations||[]):type==="group"?(groupData.groups||[]):type==="mount"?(mountData.mounts||[]):normalizeGenericEntityCards().filter(item=>item.entityType===type);for(const entity of list){const key=entitySpatialKey(entity,type),parent=entityContainerKey(entity,type);if(selected.has(parent)&&!selected.has(key)){selected.add(key);changed=true;}}}}
    return [...selected];
};
const archiveJourneyKeys = (keys,{closeModal=null,onArchived=null}={}) => {
    const roots=[...new Set((keys||[]).map(String).filter(key=>entityFromSpatialKey(key)))];if(!roots.length){new Notice("Mahzene gönderilecek mevcudat seçilmedi.");return false;}
    const allKeys=collectJourneySubtreeKeys(roots);
    const sealedRecords=allKeys.map(key=>entityFromSpatialKey(key)).filter(record=>record?.entity&&(record.entity.isImmortal===true||record.entity.undeletable===true||record.entity.canonicalAlekrythaRace===true||record.entity.canonicalAlekrythaRaceGroup===true));
    if(sealedRecords.length){new Notice(`∞ Ölümsüzlük mührü taşıyan kartlar silinemez: ${sealedRecords.slice(0,3).map(record=>fullNameOf(record.entity)).join(", ")}${sealedRecords.length>3?` +${sealedRecords.length-3}`:""}`);return false;}
    const protectedRecords=allKeys.map(key=>entityFromSpatialKey(key)).filter(record=>record?.type==="character"&&(record.entity.__special||record.entity.id===1||record.entity.id===2));if(protectedRecords.length){new Notice(`Özel karakter kayıtları mahzene gönderilemez: ${protectedRecords.map(record=>fullNameOf(record.entity)).join(", ")}`);return false;}showAlekrythaePasswordModal(async()=>{
        const batchId=makeId("forgotten_batch"),rootSet=new Set(roots),now=new Date().toISOString();
        const entries=allKeys.map(key=>{const record=entityFromSpatialKey(key);return record?{id:makeId("forgotten"),batchId,root:rootSet.has(key),key,type:record.type,name:fullNameOf(record.entity),originalContainerKey:entityContainerKey(record.entity,record.type),snapshot:cloneData(record.entity),forgottenAt:now}:null;}).filter(Boolean);
        entries.forEach(entry=>removeEntityByRecord({type:entry.type,entity:entry.snapshot}));forgottenData.entries.push(...entries);journeySelected.clear();if(allKeys.includes(currentJourneyContainerKey))currentJourneyContainerKey="root";
        await saveToDB(`${entries.length} mevcudat Unutulmuşlar Mahzeni’ne gönderildi.`);closeModal?.remove?.();renderJourney();onArchived?.(entries);new Notice(`◌ ${entries.length} mevcudat Unutulmuşlar Mahzeni’nde saklanıyor.`);
    },{title:"Unutulmuşlar Mahzeni’ne Gönder",message:`${roots.length} seçili kök mevcudat ve içlerindeki toplam ${allKeys.length} mevcudat geri çağrılabilir biçimde mahzene taşınacak. Parola: Ałek’ryŧhæ`});return true;
};
const openForgottenVault = () => {
    const wrap=document.createElement("div");wrap.className="forgotten-vault";const list=document.createElement("div");list.className="forgotten-vault-list";wrap.appendChild(list);
    const draw=()=>{
        list.innerHTML="";const entries=[...(forgottenData.entries||[])];
        const batches=[...new Set(entries.map(entry=>String(entry.batchId||entry.id)))].map(batchId=>{
            const items=entries.filter(entry=>String(entry.batchId||entry.id)===batchId).sort((a,b)=>Number(!!b.root)-Number(!!a.root));
            return {batchId,items,root:items.find(item=>item.root)||items[0]};
        }).filter(batch=>batch.root).sort((a,b)=>String(b.root.forgottenAt).localeCompare(String(a.root.forgottenAt)));
        if(!batches.length){const empty=document.createElement("div");empty.className="empty-state large";empty.innerHTML="<strong>Mahzen sessiz.</strong><span>Q + tık ile seçip Delete dediğin mevcudatlar burada mühürlü kümeler hâlinde saklanır.</span>";list.appendChild(empty);return;}
        batches.forEach(batch=>{const entry=batch.root,row=document.createElement("article");row.className="forgotten-card";const rootNames=batch.items.filter(item=>item.root).map(item=>item.name).filter(Boolean);const summary=rootNames.slice(0,3).join(", ")+(rootNames.length>3?` +${rootNames.length-3}`:"");row.title=batch.items.map(item=>item.name).filter(Boolean).join("\n");row.innerHTML=`<div class="forgotten-card-icon">${entry.type==="character"?"🍃":entry.type==="location"?"🌱":entry.type==="group"?"👥":entry.type==="mount"?"⛵":entry.type==="being"?"✥":entry.type==="dynasty"?"♜":entry.type==="society"?"⌘":"◇"}</div><div class="forgotten-card-copy"><strong>${escapeHtmlValue(summary||entry.name||"İsimsiz Mevcudat")}</strong><small>${batch.items.length} mevcudatlık mühür · ${new Date(entry.forgottenAt).toLocaleString("en-US")}</small></div>`;const actions=document.createElement("div");actions.className="forgotten-card-actions";const restore=document.createElement("button");restore.textContent="Geri Çağır";const purge=document.createElement("button");purge.className="danger";purge.textContent="Sonsuza Sil";actions.append(restore,purge);row.appendChild(actions);
            restore.onclick=async()=>{const restored=[...batch.items].sort((a,b)=>Number(!!b.root)-Number(!!a.root));for(const item of restored)restoreEntitySnapshot(item);const restoredKeys=new Set(restored.map(item=>item.key));for(const item of restored){const record=entityFromSpatialKey(item.key);if(!record)continue;const parent=String(item.originalContainerKey||"root");record.entity.containerKey=parent==="root"||entityFromSpatialKey(parent)||restoredKeys.has(parent)?parent:"root";}forgottenData.entries=(forgottenData.entries||[]).filter(item=>String(item.batchId||item.id)!==String(batch.batchId));await saveToDB(`${restored.length} mevcudat mahzenden geri çağrıldı.`);draw();if(activeV2View==="journey")renderJourney();};
            purge.onclick=()=>showAlekrythaePasswordModal(async()=>{forgottenData.entries=(forgottenData.entries||[]).filter(item=>String(item.batchId||item.id)!==String(batch.batchId));await saveToDB(`${batch.items.length} mevcudat kalıcı olarak unutuldu.`);draw();},{title:"Sonsuz Unutuş",message:`${batch.items.length} mevcudatlık bu mühür artık geri döndürülemeyecek biçimde silinecek. Parola: Ałek’ryŧhæ`});list.appendChild(row);
        });
    };draw();showV2Modal({title:"◌ Unutulmuşlar Mahzeni",body:wrap,saveText:"Mahzeni Kapat",wide:true,onSave:async()=>true});
};
const openTimeCampModal=({fromJoA=false}={})=>{
    const modes={
        wait:{label:"Bekleme",health:1,mana:1,stamina:0,metanet:.20,sleep:false,reason:"Vakit geçirildi",description:"Vakit ilerler. Can ve mana doğal hızında, metanet çok hafif toparlanır; uyku olmadığı için Takat yenilenmez.",effect:"Can ×1 · Mana ×1 · Takat ×0 · Metanet ×0,20",icon:'<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M15 7h18M15 41h18M17 8c0 8 2 11 7 16-5 5-7 8-7 16M31 8c0 8-2 11-7 16 5 5 7 8 7 16M19 12h10M19 36h10"/></svg>'},
        aid:{label:"İlk Yardım",health:1.75,mana:1.10,stamina:0,metanet:.10,sleep:false,reason:"İlk yardım uygulandı",description:"Temel bakım Canı güçlü, manayı hafif toparlar. Uyku olmadığı için Takat yenilenmez.",effect:"Can ×1,75 · Mana ×1,10 · Takat ×0 · Metanet ×0,10",icon:'<svg viewBox="0 0 48 48" aria-hidden="true"><rect x="8" y="16" width="32" height="16" rx="8"/><path d="M16 16l16 16M32 16L16 32M24 19v10M19 24h10"/></svg>'},
        camp:{label:"Kamp Kurma",health:2.25,mana:1.75,stamina:1.15,metanet:.80,sleep:true,reason:"Kamp kuruldu ve uyundu",description:"Kamp uykusu dört kaynağı da yeniler. Takat yalnız uyku içeren seçeneklerde doğal saatlik değeriyle çalışır.",effect:"Can ×2,25 · Mana ×1,75 · Takat ×1,15 · Metanet ×0,80",icon:'<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M6 39h36M10 39L24 10l14 29M15 39l9-18 9 18M24 21v18"/><path d="M34 10c3 2 4 5 3 8"/></svg>'},
        inn:{label:"Yatak / Han",health:3,mana:2.5,stamina:1.60,metanet:1.35,sleep:true,reason:"Han yatağında uyundu",description:"Konforlu uyku dört kaynağın da en güçlü doğal toparlanmasını sağlar.",effect:"Can ×3 · Mana ×2,50 · Takat ×1,60 · Metanet ×1,35",icon:'<svg viewBox="0 0 48 48" aria-hidden="true"><path d="M7 37V16M41 37V25H18c-4 0-7 3-7 7v5M7 31h34M11 20h10c3 0 5 2 5 5H11zM7 40v-3M41 40v-3"/></svg>'}
    };
    let selectedMode="wait";
    const wrap=document.createElement("div");wrap.className="time-camp-panel";
    const current=document.createElement("div");current.className="time-current-seal";current.innerHTML=`<small>Şimdiki Vakit</small><strong>${formatGameTime()}</strong>`;
    const modeField=document.createElement("div");modeField.className="time-rest-mode-field";
    const modeTitle=document.createElement("span");modeTitle.textContent="Dinlenme Biçimi";
    const modeGrid=document.createElement("div");modeGrid.className="time-rest-mode-grid";modeGrid.setAttribute("role","radiogroup");modeGrid.setAttribute("aria-label","Dinlenme biçimi");
    const modeButtons=new Map();
    const selectMode=key=>{if(!modes[key])return;selectedMode=key;modeButtons.forEach((button,id)=>button.setAttribute("aria-checked",String(id===selectedMode)));sync();};
    Object.entries(modes).forEach(([key,definition])=>{
        const button=document.createElement("button");button.type="button";button.className="time-rest-mode";button.setAttribute("role","radio");button.setAttribute("aria-checked",String(key===selectedMode));button.dataset.mode=key;
        button.innerHTML=`<span class="time-rest-mode-icon">${definition.icon}</span><strong>${definition.label}</strong>${definition.sleep?'<small>UYKU</small>':''}`;
        button.onclick=()=>selectMode(key);
        button.onkeydown=e=>{if(!["ArrowLeft","ArrowRight","ArrowUp","ArrowDown"].includes(e.key))return;e.preventDefault();const keys=Object.keys(modes),delta=(e.key==="ArrowRight"||e.key==="ArrowDown")?1:-1,next=(keys.indexOf(selectedMode)+delta+keys.length)%keys.length;selectMode(keys[next]);modeButtons.get(keys[next])?.focus();};
        modeButtons.set(key,button);modeGrid.appendChild(button);
    });
    modeField.append(modeTitle,modeGrid);
    const days=document.createElement("input");days.type="number";days.min="0";days.step="1";days.value="0";
    const hours=document.createElement("input");hours.type="number";hours.min="0";hours.step="1";hours.value="1";
    const minutes=document.createElement("input");minutes.type="number";minutes.min="0";minutes.max=normalizeGameRuntime().mode==="alekrytha"?String(ALEK_MINUTES_PER_HOUR-1):"59";minutes.step="1";minutes.value="0";
    const daysField=document.createElement("label");daysField.className="time-duration-field";daysField.innerHTML="<span>Gün</span>";daysField.appendChild(days);
    const hoursField=document.createElement("label");hoursField.className="time-duration-field";hoursField.innerHTML="<span>Saat</span>";hoursField.appendChild(hours);
    const minutesField=document.createElement("label");minutesField.className="time-duration-field";minutesField.innerHTML="<span>Dakika</span>";minutesField.appendChild(minutes);
    const preview=document.createElement("div");preview.className="time-camp-preview";
    function totalSeconds(){const runtimeMode=normalizeGameRuntime().mode;return runtimeMode==="alekrytha"?Math.max(0,Math.floor(Number(days.value)||0))*ALEK_SECONDS_PER_DAY+Math.max(0,Math.floor(Number(hours.value)||0))*ALEK_SECONDS_PER_HOUR+Math.max(0,Math.min(ALEK_MINUTES_PER_HOUR-1,Math.floor(Number(minutes.value)||0)))*ALEK_SECONDS_PER_MINUTE:Math.max(0,Math.floor(Number(days.value)||0))*86400+Math.max(0,Math.floor(Number(hours.value)||0))*3600+Math.max(0,Math.min(59,Math.floor(Number(minutes.value)||0)))*60;}
    function sync(){const total=totalSeconds(),definition=modes[selectedMode];preview.innerHTML=`<strong>${definition.label}${definition.sleep?' · Uyku':''}</strong><span>${definition.description}</span><small>${definition.effect}${total?` · ${formatDurationSeconds(total)} ilerleyecek`:" · İlerleyecek süreyi seç"}</small>`;}
    days.oninput=hours.oninput=minutes.oninput=sync;sync();
    wrap.append(current,modeField,daysField,hoursField,minutesField,preview);
    const modal=showV2Modal({title:"Vakit Ocağı · Dinlenme ve Zaman Atlama",body:wrap,saveText:"Vakti İlerle",wide:true,onSave:async()=>{
        const seconds=totalSeconds();if(!seconds){new Notice("İlerleyecek süreyi seç.");return false;}
        const definition=modes[selectedMode];
        const result=advanceGameSeconds(seconds,{persist:false,reason:definition.reason,healthRecoveryMultiplier:definition.health,manaRecoveryMultiplier:definition.mana,staminaRecoveryMultiplier:definition.sleep?definition.stamina:0,metanetRecoveryMultiplier:definition.metanet});
        await saveToDB(null);
        new Notice(`${selectedMode==="wait"?"⌛":selectedMode==="aid"?"✚":selectedMode==="camp"?"△":"▰"} ${definition.label} · ${formatDurationSeconds(seconds)} · Can +${result.recovery.health}, Mana +${result.recovery.mana}, Takat +${result.recovery.stamina}, Metanet +${result.recovery.metanet}`);
        if(fromJoA){window.dispatchEvent(new CustomEvent("alek:joa-time-refreshed",{detail:{gameTime:formatGameTime()}}));}
        else if(__alekUnifiedActiveRecord?.entity)openUnifiedEntityDetail(__alekUnifiedActiveRecord,{pushCurrent:false});else renderJourney();return true;
    }});
    return modal;
};
