const JOURNEY_TAXONOMY_TYPE_BY_LABEL=Object.freeze(Object.fromEntries(Object.entries(JOURNEY_TAXONOMY_LABEL_BY_TYPE).map(([type,label])=>[label,type])));
const journeyCardTypeSigilMarkup=(visual,type)=>{const taxonomyLabel=JOURNEY_TAXONOMY_LABEL_BY_TYPE[type],sharedSigil=taxonomyLabel?JOURNEY_TAXONOMY_SYMBOLS?.[taxonomyLabel]:null;return `<span class="journey-card-kind-sigil ${type}" aria-hidden="true">${sharedSigil||visual.typeSigil}</span>`;};
const bindJourneyIdentityBadge=badge=>{
    if(!badge||badge.dataset.identityBadgeBound==="true")return badge;
    badge.dataset.identityBadgeBound="true";
    badge.tabIndex=0;
    badge.style.setProperty("pointer-events","auto","important");
    const expand=()=>badge.classList.add("is-expanded");
    const collapse=()=>badge.classList.remove("is-expanded");
    badge.addEventListener("pointerenter",expand);
    badge.addEventListener("pointerleave",collapse);
    badge.addEventListener("focus",expand);
    badge.addEventListener("blur",collapse);
    return badge;
};
const journeyCardSubtype=(item,type)=>{
    if(type==="character")return item.className?`Class · ${item.className}`:(item.title||item.gender||"Karakter");
    if(type==="location")return item.spatialKind==="mobile_area"?"Hareketli Alan":item.spatialKind==="mobile_pawn"?"Hareketli Piyon":"Coğrafi Mekân";
    if(type==="land")return item.spatialKind==="mobile_area"?"Hareketli Diyar":item.spatialKind==="mobile_pawn"?"Gezgin Diyar":"Diyar";
    if(type==="group")return `${item.groupType||"Grup"} · ${groupDirectMembers(item).length} kart`;
    if(type==="mount")return `${item.mountType||"Binek / Taşıt"} · ${Number(item.travelSpeed)||0} metre/saniye`;
    if(ALEK_GENERIC_ENTITY_TYPES.includes(type))return item.subtype||item.title||genericEntityDefinition(type)?.title||"Varlık";
    return "";
};
const applyJourneyPortraitGeometry=(card,ratio)=>{
    if(!card||!(ratio>0))return;
    // Portresiz kanonik kartın boyu korunur. Kare ve yatay görseller yalnız enine
    // açılır; ancak görsel bu tabandan daha darsa kart boyuna uzar.
    const baseWidth=226,baseHeight=343,baseRatio=baseWidth/baseHeight;
    const maxWidth=820,maxHeight=760;
    let width=baseWidth,height=baseHeight;
    if(ratio>=baseRatio)width=Math.min(maxWidth,Math.max(baseWidth,Math.round(baseHeight*ratio)));
    else height=Math.min(maxHeight,Math.max(baseHeight,Math.round(baseWidth/ratio)));
    card.classList.add("portrait-ratio-card");
    card.classList.toggle("portrait-ratio-narrow",ratio<baseRatio);
    card.classList.toggle("portrait-ratio-wide",ratio>1.15);
    card.dataset.portraitRatio=ratio.toFixed(4);
    card.style.setProperty("width",`${width}px`,"important");
    card.style.setProperty("min-width",`${width}px`,"important");
    card.style.setProperty("max-width",`${width}px`,"important");
    card.style.setProperty("flex-basis",`${width}px`,"important");
    card.style.setProperty("height",`${height}px`,"important");
    card.style.setProperty("min-height",`${height}px`,"important");
    card.style.setProperty("max-height",`${height}px`,"important");
};
const makeJourneyCard = (item,type) => {
    const visual=JOURNEY_CARD_VISUALS[type]||JOURNEY_CARD_VISUALS.character;
    const card=document.createElement("div");
    // Karakter, görünümde Varlık kartının birebir yüzeyini kullanır.
    // Gerçek tür yalnız dataset ve veri anahtarında character olarak korunur.
    const surfaceType=type==="character"?"being":type;
    card.className=`journey-card ${surfaceType} journey-card-v27 journey-card-v28 journey-card-v29 journey-card-v32 journey-card-v33 journey-card-v35`;
    card.dataset.key=`${type}:${item.id}`;
    card.dataset.cardType=type;
    card.dataset.identityType=type;
    card.style.setProperty("--card-accent",cardIdentityAccentOf(type),"important");
    card.setAttribute("role","button");
    card.tabIndex=0;
    card.style.touchAction="manipulation";

    const rawName=String(fullNameOf(item)||"").trim();
    const displayName=rawName||(
        type==="character"?"İsimsiz Karakter":
        type==="location"?"İsimsiz Mekân":
        type==="group"?"İsimsiz Grup":
        type==="mount"?"İsimsiz Binek / Taşıt":`İsimsiz ${genericEntityDefinition(type)?.title||"Varlık"}`
    );
    const displaySubtitle=String(
        type==="character"?(item.title||item.className||item.gender||"Karakter"):
        type==="location"?(item.title||"Mekân"):
        type==="land"?(item.title||"Diyar"):
        type==="group"?(item.description||item.groupType||"Grup"):
        type==="mount"?(item.title||item.mountType||"Binek / Taşıt"):
        (item.subtype||item.title||genericEntityDefinition(type)?.title||"Varlık")
    ).trim()||visual.label;

    card.setAttribute("aria-label",`${visual.label}: ${displayName}`);
    card.title=`${displayName} · Normal tık: kart kağıdı · E + tık: konteynerin içine gir`;
    if(journeySelected.has(card.dataset.key))card.classList.add("selected");
    if(item.isDead)card.classList.add("dead");

    const imagePath=String(item.avatar||item.image||"").trim();
    const shell=document.createElement("img");
    shell.className="journey-card-shell";
    shell.src=getDynamicUrl(imagePath?"Assets/character_card_frame.png":"Assets/card_shell_master.png");
    shell.alt="";
    shell.draggable=false;
    shell.setAttribute("aria-hidden","true");

    const typeBanner=document.createElement("div");
    typeBanner.className="journey-card-type-banner";
    typeBanner.style.setProperty("--kind-sigil-color",cardIdentityAccentOf(type),"important");
    typeBanner.title=visual.label;
    typeBanner.setAttribute("aria-label",visual.label);
    typeBanner.innerHTML=`${journeyCardTypeSigilMarkup(visual,type)}<span>${visual.label}</span>`;
    bindJourneyIdentityBadge(typeBanner);

    const subtype=document.createElement("div");
    subtype.className="journey-card-subtype";
    subtype.textContent=journeyCardSubtype(item,type);

    const info=document.createElement("div");
    info.className="journey-card-info";
    const name=document.createElement("strong");
    name.textContent=displayName;
    const title=document.createElement("small");
    title.textContent=displaySubtitle;
    info.append(name,title);

    [shell,subtype,info].forEach(node=>node.style.pointerEvents="none");
    card.append(shell,typeBanner,subtype,info);
    // Kaynak şeridi yalnız gerçekten kaynak taşıyan kart ailelerinde gösterilir.
    // Konteyner olmak artık bütün kartların ortak kabiliyetidir.
    if(usesIndividualSheetType(type)||type==="mount"||isCollectiveEntityType(type)||isInstitutionEntityType(type)){
        const resourceStrip=document.createElement("div");
        resourceStrip.className=`journey-card-resource-strip ${entityBehaviorFamily(type)}`;
        resourceStrip.style.pointerEvents="none";
        let firstLabel="CAN",secondLabel="MANA",first={current:0,maximum:0},second={current:0,maximum:0};
        if(usesIndividualSheetType(type)){
            ensureEntitySheetFields(item,"character");
            first=ensureCharacterHealth(item);second=ensureArcanaReserve(item);
        }else if(isCollectiveEntityType(type)){
            const total=collectiveResourceTotals({type,entity:item,key:entitySpatialKey(item,type)});
            first=total.health;second=total.mana;
        }else if(isInstitutionEntityType(type)){
            ensureInstitutionResources(item);
            firstLabel="NÜFUZ";secondLabel="İTİBAR";first=item.influence;second=item.reputation;
        }else{
            // Binek/Taşıt kartının kaynakları kendi varlığına aittir.
            ensureEntitySheetFields(item,"mount");
            first=ensureCharacterHealth(item);second=ensureArcanaReserve(item);
        }
        const line=(label,pool)=>{
            const max=Math.max(0,Number(pool.maximum)||0),cur=Math.max(0,Number(pool.current)||0),ratio=max?Math.max(0,Math.min(100,cur/max*100)):0;
            return `<span><small>${label}</small><i><b style="width:${ratio}%"></b></i><em>${cur}/${max}</em></span>`;
        };
        resourceStrip.innerHTML=line(firstLabel,first)+line(secondLabel,second);
        card.insertBefore(resourceStrip,info);
    }
    const directChildCount=directJourneyEntityRecords(card.dataset.key).length;
    if(directChildCount){
        const countBadge=document.createElement("span");
        countBadge.className="journey-card-container-count";
        countBadge.textContent=String(directChildCount);
        countBadge.title=`İçinde ${directChildCount} kart var`;
        card.appendChild(countBadge);
    }
    card.classList.add("has-moon-motif");

    // Portre katmanı yalnız resim GERÇEKTEN yüklendiğinde karta eklenir.
    // Böylece bozuk/eski yol, Mavi Ayı ve alt bilgi panelini asla örtemez.
    if(imagePath){
        const imageWrap=document.createElement("div");
        imageWrap.className="journey-image journey-card-artwork";
        imageWrap.style.pointerEvents="none";

        const img=document.createElement("img");
        img.className="journey-card-portrait";
        img.alt=displayName;
        img.draggable=false;
        img.style.pointerEvents="none";
        imageWrap.style.setProperty("background","radial-gradient(circle at 50% 38%,#183246,#02070b 74%)","important");
        img.style.setProperty("object-fit","cover","important");
        img.style.setProperty("object-position","center 32%","important");

        let settled=false;
        const useMoonFallback=()=>{
            if(settled)return;
            settled=true;
            card.classList.remove("has-portrait","portrait-loaded");
            card.classList.add("has-moon-motif","portrait-fallback");
            imageWrap.remove();
        };
        img.onload=()=>{
            if(settled)return;
            settled=true;
            const ratio=(Number(img.naturalWidth)||1)/(Number(img.naturalHeight)||1);
            const wide=ratio>1.28;
            img.style.setProperty("object-fit","contain","important");
            img.style.setProperty("object-position","center center","important");
            imageWrap.classList.toggle("wide-artwork",wide);
            card.classList.remove("has-moon-motif","portrait-fallback");
            card.classList.add("has-portrait","portrait-loaded");
            // Karakter kartında resim oranı şablonu yönetir: yükseklik sabitken en genişler,
            // yalnız taban karttan daha dar oranlarda kart boydan uzar. Resim asla kırpılmaz.
            if(type==="character")applyJourneyPortraitGeometry(card,ratio);
            card.insertBefore(imageWrap,info);
        };
        img.onerror=useMoonFallback;
        imageWrap.appendChild(img);
        img.src=getDynamicUrl(imagePath);
        // Bazı WebView2 durumlarında tamamlanmış fakat bozuk görsel onerror üretmeyebilir.
        queueMicrotask(()=>{
            if(img.complete&&(!img.naturalWidth||!img.naturalHeight))useMoonFallback();
        });
    }

    if(isContainerEntityType(type)&&[...journeySelected].some(key=>key!==card.dataset.key)){
        card.classList.add("journey-drop-target");
        card.title=`Normal tık kart kağıdını açar · E + tık konteynere girer ve seçili ${[...journeySelected].filter(key=>key!==card.dataset.key).length} kartı korur · Taşıma Mevcudat ağacında W + tık ile yapılır.`;
    }
    if(type!=="character"&&type!=="being"&&type!=="group"&&type!=="mount"&&!ALEK_GENERIC_ENTITY_TYPES.includes(type))alekApplyJourneyCardState(card,item);

    const openCardEditor=initialTab=>openUnifiedEntityDetail({type,entity:item,key:entitySpatialKey(item,type)},{pushCurrent:true,initialTab});

    let activationBusy=false;
    const activate = async e => {
        e?.preventDefault?.();
        e?.stopPropagation?.();
        if(activationBusy)return;
        activationBusy=true;
        try {
            const key=card.dataset.key;
            if(keyQDown){
                const scrollSnapshot=captureAlekStableScroll();
                qKeyUsedForSelection=true;
                journeySelected.has(key)?journeySelected.delete(key):journeySelected.add(key);
                card.classList.toggle("selected",journeySelected.has(key));
                blurWithoutScroll(card);restoreAlekStableScroll(scrollSnapshot);
                return;
            }
            if(isSPointerIntent()){
                consumeSPointerIntent();
                openCardEditor(null);
                return;
            }
            if(isEPointerIntent()){
                // E + tık gerçek kart konteynerine girer ve Q seçimini korur.
                consumeEPointerIntent();
                openJourneyContainerInterface(key,{preserveSelection:true});
                return;
            }
            openCardEditor(null);
        } catch (cardError) {
            console.error("Journey kartı açılamadı:", cardError, {type,item});
            new Notice("🛑 Kart açılamadı: "+(cardError?.message||cardError),7000);
        } finally {
            setTimeout(()=>{activationBusy=false;},0);
        }
    };

    // Kart tek bir normal click yüzeyidir. Pointer-up/click çift yakalama kaldırıldı;
    // WebView2'de kartın kilitli görünmesine yol açan yarış durumu böylece oluşmaz.
    card.inert=false;
    card.style.pointerEvents="auto";
    card.addEventListener("click",e=>{void activate(e);});
    card.addEventListener("keydown",e=>{
        if(e.key==="Enter"||e.key===" "){e.preventDefault();void activate(e);}
    });
    card.addEventListener("contextmenu",e=>{e.preventDefault();e.stopPropagation();});
    return card;
};

const locationIsDescendant = (targetId, possibleAncestorId) => {
    let cur=getLocationById(targetId);const seen=new Set();
    while(cur&&cur.parentLocationId!=null&&!seen.has(String(cur.id))){if(String(cur.parentLocationId)===String(possibleAncestorId))return true;seen.add(String(cur.id));cur=getLocationById(cur.parentLocationId);}return false;
};
const buildBreadcrumb = () => {
    const bar=document.createElement("div");bar.className="journey-breadcrumb";const root=document.createElement("button");root.textContent="Ana Dünya";root.onclick=()=>enterJourneyContainer("root",{preserveSelection:journeySelected.size>0});bar.appendChild(root);
    containerChain(currentJourneyContainerKey).forEach(record=>{const sep=document.createElement("span");sep.textContent="›";const b=document.createElement("button");b.textContent=fullNameOf(record.entity);b.onclick=()=>enterJourneyContainer(record.key,{preserveSelection:true});bar.append(sep,b);});return bar;
};

const nextEntityNumber = (kind) => {
    const list=kind==="location"?(locationData.locations||[]):getAllCharacters().filter(c=>!c.__special);
    const re=kind==="location"?/^Yeni Mekân\s+(\d+)$/i:/^Yeni Karakter\s+(\d+)$/i;
    return Math.max(0,...list.map(x=>Number((String(x.name||"").match(re)||[])[1])||0))+1;
};
const createNewCharacter = async () => {
    const n=nextEntityNumber("character");
    const generatedName=genName(2,4),generatedSurname=genName(2,3);
    const c=normalizeLegacyCharacter({
        id:makeId("character"),name:generatedName,surname:generatedSurname,title:`Yolcu ${n}`,gender:p(["Erkek","Kadın"]),
        race:"İnsan",avatar:"",image:"",voiceProfile:"",isMain:false,isLocked:false,isDead:false,
        containerKey:currentJourneyContainerKey,locationId:currentJourneyLocationId,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()
    },false);
    ensureAlekrythaSpeciesBinding(c);
    currentState.characters.push(c);
    await saveToDB(`${c.name} oluşturuldu.`);
    renderJourney();
};
const createNewLocation = async () => {
    const n=nextEntityNumber("location");
    const generatedName=genName(2,4),generatedSurname=genName(2,3);
    const loc=normalizeLocation({
        id:makeId("location"),name:generatedName,surname:generatedSurname,title:`Mekân ${n}`,gender:"Cinsiyetsiz",
        race:"",alekrythaeRace:"",raceMode:"alekrythae",avatar:"",image:"",isLocked:false,isDead:false,
        containerKey:currentJourneyContainerKey,parentLocationId:currentJourneyLocationId,spatialKind:"geographic",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()
    });
    locationData.locations.push(loc);
    await saveToDB(`${loc.name} oluşturuldu.`);
    renderJourney();
};
const editLocation = location => openLegacyCharacter(normalizeLocation(location));
const createNewMount = async () => {
    const n=Math.max(0,...(mountData.mounts||[]).map(mount=>Number((String(mount.name||"").match(/^Yeni (?:Binek|Binek \/ Taşıt)\s+(\d+)$/i)||[])[1])||0))+1;
    const mount=normalizeMount({id:makeId("mount"),name:`Yeni Binek / Taşıt ${n}`,mountType:"At",title:"At",description:"",avatar:"",image:"",travelSpeed:JOA_MOUNT_TRAVEL_SPEED_MPS,travelSpeedUnit:JOA_TRAVEL_SPEED_UNIT,visionBonus:0,carryingCapacity:100,containerKey:currentJourneyContainerKey,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});
    mountData.mounts.push(mount);await saveToDB(`${mount.name} oluşturuldu.`);renderJourney();
};
const editMount = mount => openMountEditor(normalizeMount(mount));
const createNewGroup = async () => {
    const n=Math.max(0,...(groupData.groups||[]).map(group=>Number((String(group.name||"").match(/^Yeni Grup\s+(\d+)$/i)||[])[1])||0))+1;
    const group=normalizeGroup({id:makeId("group"),name:`Yeni Grup ${n}`,groupType:"Macera Grubu",title:"Macera Grubu",description:"",avatar:"",image:"",containerKey:currentJourneyContainerKey,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()});
    groupData.groups.push(group);await saveToDB(`${group.name} oluşturuldu.`);renderJourney();
};
const createNewGenericEntity=async type=>{
    const def=genericEntityDefinition(type);if(!def)return null;
    const same=normalizeGenericEntityCards().filter(item=>item.entityType===type);
    const n=Math.max(0,...same.map(item=>Number((String(item.name||"").match(new RegExp(`^Yeni ${def.title.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}\\s+(\\d+)$`,"i"))||[])[1])||0))+1;
    const item=normalizeGenericEntity({id:makeId(type),entityType:type,name:`Yeni ${def.title} ${n}`,title:def.title,subtype:def.title,description:"",lore:"",avatar:"",image:"",containerKey:currentJourneyContainerKey,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()},type);
    genericEntityCards().push(item);await saveToDB(`${item.name} oluşturuldu.`);renderJourney();return item;
};
const addNormalCharacter = createNewCharacter;

