        (locationData.locations||[]).filter(l=>String(l.parentLocationId??"")===String(parentId??"")).sort((a,b)=>String(a.name).localeCompare(String(b.name),"tr")).forEach(l=>{out.push({id:l.id,label:`${"　".repeat(depth)}↳ ${l.name}`});walk(l.id,depth+1);});
