    host.innerHTML=`<div class="container-inline-character-shell">${arcanaReserveMarkup(entity)}<div class="container-inline-character-main">${characterVitalsMarkup(entity)}<div class="container-inline-sheet-body"></div></div></div>`;
    bindCharacterIdentityEditor(entity,host);
    mountCharacterVitals(entity,host);
    mountArcanaReserve(entity,host);
    mountStamina(entity,host);
    mountMetanet(entity,host);
    const body=host.querySelector(".container-inline-sheet-body");
