    const width=Math.max(1,Math.floor(rect.width*ratio)),height=Math.max(1,Math.floor(rect.height*ratio));
    if(canvas.width!==width||canvas.height!==height){canvas.width=width;canvas.height=height;}
    const state=ensureJourney3DState(),active=activeWorldPiece(state),project=(x,y,z)=>journeyProjectPoint(state,width,height,x,y,z),is3d=state.camera.viewMode==="3d";
    runtime.hitPieces=[];runtime.hitRegions=[];

    // Yaşayan Dünya Masası: boş neon grid yerine koyu deniz/parşömen yüzeyi.
    const sea=ctx.createLinearGradient(0,0,width,height);sea.addColorStop(0,"#101a1a");sea.addColorStop(.46,"#0b1618");sea.addColorStop(1,"#16130e");ctx.fillStyle=sea;ctx.fillRect(0,0,width,height);
    const vignette=ctx.createRadialGradient(width*.5,height*.45,Math.min(width,height)*.08,width*.5,height*.5,Math.max(width,height)*.72);vignette.addColorStop(0,"rgba(91,126,112,.08)");vignette.addColorStop(.58,"rgba(5,10,11,.05)");vignette.addColorStop(1,"rgba(0,0,0,.58)");ctx.fillStyle=vignette;ctx.fillRect(0,0,width,height);
    ctx.save();ctx.globalAlpha=.18;ctx.strokeStyle="rgba(157,177,157,.13)";ctx.lineWidth=Math.max(1,ratio*.55);
    for(let i=0;i<18;i++){const y=(i+.5)*height/18+Math.sin(i*1.73)*7*ratio;ctx.beginPath();for(let x=0;x<=width;x+=24*ratio){const yy=y+Math.sin(x/(75*ratio)+i*.61)*3.2*ratio+Math.sin(x/(173*ratio)+i)*2*ratio;x===0?ctx.moveTo(x,yy):ctx.lineTo(x,yy);}ctx.stroke();}
    ctx.restore();

