        const boundary=journeyRegionBoundary(region,draft?48:72),screen=boundary.map(p=>project(p.x,0,p.z)).filter(Boolean);if(screen.length<3)return;
        const hash=journeyHash(region.id||region.name),palette=regionColors[hash%regionColors.length];
        ctx.save();ctx.beginPath();screen.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();
