    const discovered=new Set(state.discoveries.map(item=>String(item.id)));
    journeyLoreNodes().filter(node=>node.layerKey===state.layerKey&&discovered.has(String(node.id))).forEach(node=>{const point=project(node.x,.2,node.z);if(!point)return;ctx.save();ctx.translate(point.x,point.y);ctx.rotate(Math.PI/4);ctx.fillStyle="#d6b566";ctx.strokeStyle="#f2ead5";ctx.lineWidth=1*ratio;ctx.fillRect(-4.5*ratio,-4.5*ratio,9*ratio,9*ratio);ctx.strokeRect(-4.5*ratio,-4.5*ratio,9*ratio,9*ratio);ctx.restore();});

    const linkedRegionLocations=new Set(state.regions.filter(region=>region.layerKey===state.layerKey).map(region=>String(region.locationId)));
    const pieces=Object.entries(state.pieces).map(([key,piece])=>({record:entityFromSpatialKey(key),key,piece})).filter(item=>item.record&&item.piece.layerKey===state.layerKey&&!(item.record.type==="location"&&item.record.entity.spatialKind==="geographic"&&linkedRegionLocations.has(String(item.record.entity.id))));
    pieces.sort((a,b)=>{const pa=project(a.piece.x,.2,a.piece.z),pb=project(b.piece.x,.2,b.piece.z);return(pa?.depth||0)-(pb?.depth||0);});
