        if(worldRadius){const edge=project(piece.x+worldRadius,0,piece.z);if(edge){ctx.save();ctx.beginPath();ctx.arc(point.x,point.y,Math.abs(edge.x-point.x),0,Math.PI*2);ctx.fillStyle="rgba(192,155,79,.08)";ctx.fill();ctx.strokeStyle=selected?"rgba(246,214,133,.88)":"rgba(190,163,104,.48)";ctx.setLineDash([7*ratio,6*ratio]);ctx.stroke();ctx.restore();}}
        // Bütün hareketli harita piyonları fiziksel ölçekte tam 1 metre çapındadır.
