        if(tokenDiameterPx>=16||selected){ctx.font=`800 ${Math.max(10,10.5*ratio)}px Segoe UI`;ctx.textAlign="center";ctx.textBaseline="top";const label=fullNameOf(record.entity);ctx.lineWidth=3*ratio;ctx.strokeStyle="rgba(5,8,8,.92)";ctx.strokeText(label,point.x,point.y+Math.max(tokenRadius,3*ratio)+6*ratio);ctx.fillStyle=selected?"#ffe7a7":"#e2e8dc";ctx.fillText(label,point.x,point.y+Math.max(tokenRadius,3*ratio)+6*ratio);}ctx.restore();
