// İmge Paleti küresel kısayolu. Alt+G paleti açar; F2 Ana Daireyi açar.
document.addEventListener("keydown",e=>{
    const key=String(e.key||"").toLowerCase();
    const altG=e.altKey&&!e.ctrlKey&&!e.shiftKey&&!e.metaKey&&key==="g";
    const altS=e.altKey&&!e.ctrlKey&&!e.metaKey&&key==="s";
    if(altG){
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        if(!e.repeat) openEmojiKeyboard();
    }
    if(altS){/* Eski Runtime bildirimi yalnız sessizce tüketilir. */}
},true);
document.addEventListener("keyup",e=>{
    const key=String(e.key||"").toLowerCase();
    if(e.altKey&&!e.ctrlKey&&!e.metaKey&&key==="s"){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();}
},true);

// Tam Kağıt ESC ile kapanır; üstte bir modal varsa önce o modal kendi ESC davranışını kullanır.
document.addEventListener("keydown",e=>{
    if(e.key!=="Escape"||!__alekUnifiedActiveRecord)return;
    if(document.querySelector(".taxonomy-circle-shade.r70,.shortcut-atlas-shade,.alek-primary-radial-shade,.joa-crop-modal.open,.v2-modal-overlay"))return;
    e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();closeLegacyCharacter({useHistory:false});
},true);

// Kağıt ayrıntısı geçmişi yalnız Alt+E tarafından kullanılır.
document.addEventListener("keydown",e=>{
    const target=e.target,key=String(e.key||"").toLowerCase();
    if(!e.altKey||e.ctrlKey||e.metaKey||key!=="e"||!__alekUnifiedActiveRecord)return;
    if(target&&((target.matches&&target.matches("input,textarea,select"))||target.isContentEditable))return;
    e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();closeLegacyCharacter();
},true);

