document.head.appendChild(v50ViewportClosureStyle);

// Dönüşüm ölçeği altında yüzde yüksekliklerinin yuvarlanma hatasını tek piksele kadar kapat.
const syncV50ViewportHeight=()=>{
  const shell=document.getElementById("alekV2Shell");
  const content=shell?.querySelector(":scope > .alek-v2-content");
  if(!shell?.isConnected||!content?.isConnected)return;
  // v51: yüksekliği JavaScript ile ikinci kez daraltma. Grid'in minmax(0,1fr) satırı gerçek kalan alanı yönetir.
  content.style.removeProperty("height");
  content.style.removeProperty("max-height");
};
requestAnimationFrame(()=>requestAnimationFrame(syncV50ViewportHeight));
window.addEventListener("resize",syncV50ViewportHeight,{passive:true});
try{
  const v50ResizeObserver=new ResizeObserver(syncV50ViewportHeight);
  const shell=document.getElementById("alekV2Shell");
  const masthead=shell?.querySelector(".v9-masthead");
  const nav=shell?.querySelector(".alek-v2-nav");
  if(shell)v50ResizeObserver.observe(shell);if(masthead)v50ResizeObserver.observe(masthead);if(nav)v50ResizeObserver.observe(nav);
}catch(_){}


// v0.0.0-53 · v51 tabanından tek kaynaklı karakter kolonları ve gerçek kullanılabilir yüzey düzeni.
const v53LayoutStyle=document.createElement("style");
