v59AlignmentStyle.id="alekV59AlignmentStyle";
v59AlignmentStyle.textContent=`
/* İlk açılıştaki Mavi Ay kalp atışı gibi sekmez; iki uç arasında kesintisiz, yumuşak nefes alır. */
.alek-opening-moon{
  animation:alekV59OpeningBreath 2.05s ease-in-out infinite alternate!important;
  will-change:transform,opacity,filter!important;
}
.alek-opening-moon img{animation:none!important;opacity:1!important;filter:none!important;transform:none!important}
@keyframes alekV59OpeningBreath{
  from{transform:scale(.985);opacity:.82;filter:brightness(.88) saturate(.96) drop-shadow(0 0 28px rgba(70,179,239,.48)) drop-shadow(0 0 68px rgba(22,102,196,.28))}
  to{transform:scale(1.025);opacity:1;filter:brightness(1.26) saturate(1.14) drop-shadow(0 0 46px rgba(145,230,255,.84)) drop-shadow(0 0 104px rgba(45,143,238,.48))}
}

/* v58'in daraltması kaldırılır; v57'nin masthead yüksekliği ve oranları geri gelir. */
#alekV2Shell>.v9-masthead{
  height:64px!important;
  min-height:66px!important;
  max-height:none!important;
  flex:0 0 66px!important;
  padding:0 70px 0 22px!important;
  align-items:center!important;
  box-sizing:border-box!important;
}
#alekV2Shell .v9-brand-lockup{height:auto!important;align-self:stretch!important}
#alekV2Shell .v9-core-orb{width:46px!important;height:46px!important;flex-basis:46px!important}

/* Kabuğun %90 CSS zoom + %111,111 genişlik düzeninde görsel merkez layout merkezinin %45'idir.
   Başlık ve menüler bu gerçek görsel merkeze bağlanır; sağ sürüm alanı da görünür sağ sınıra alınır. */
#alekV2Shell .v9-masthead-center{
  left:45%!important;
  top:50%!important;
  transform:translate(-50%,-50%)!important;
}
#alekV2Shell .v9-edition{
  right:calc(10% + 64px)!important;
  top:50%!important;
  transform:translateY(-50%)!important;
  max-width:31%!important;
}
#alekV2Shell>.v9-masthead::before,
#alekV2Shell>.v9-masthead::after{right:calc(10% + 22px)!important}

/* Menü grubunun merkezini de aynı görsel merkeze taşır; çubuğun arka planı ve çerçevesi yerinde kalır. */
#alekV2Shell>.alek-v2-nav{
  justify-content:center!important;
  padding-left:18px!important;
  padding-right:calc(10% + 18px)!important;
  box-sizing:border-box!important;
}

@media(max-width:1320px){#alekV2Shell .v9-edition span{display:none!important}}
@media(max-width:1100px){
  #alekV2Shell>.alek-v2-nav{justify-content:flex-start!important;padding-right:calc(10% + 18px)!important}
}
@media(max-width:820px){
  #alekV2Shell>.v9-masthead{height:58px!important;min-height:58px!important;max-height:58px!important;flex:0 0 58px!important;padding:0 54px 0 13px!important}
  #alekV2Shell .v9-brand-lockup{height:58px!important}
  #alekV2Shell .v9-core-orb{width:40px!important;height:40px!important;flex-basis:40px!important}
  #alekV2Shell .v9-edition{right:calc(10% + 48px)!important}
}
`;
document.head.appendChild(v59AlignmentStyle);

const v60HybridAndLegacyAuditStyle=document.createElement("style");
v60HybridAndLegacyAuditStyle.id="alekV60HybridAndLegacyAuditStyle";
v60HybridAndLegacyAuditStyle.textContent=`
/* v60 · Melez seçim sözleşmesi */
.hybrid-race-panel{grid-template-columns:minmax(0,1fr)!important;grid-template-rows:minmax(0,1fr) auto!important;gap:0!important;padding:0!important;overflow:hidden!important;max-height:min(360px,43vh)!important;background:#090b10!important;}
.hybrid-race-scroll{min-height:0;overflow-y:auto;overflow-x:hidden;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-rows:minmax(34px,auto);gap:6px 12px;padding:12px 13px 10px;box-sizing:border-box;align-content:start;scrollbar-gutter:stable;}
.hybrid-race-scroll>label{min-width:0;display:grid!important;grid-template-columns:auto auto minmax(0,1fr)!important;align-items:center!important;gap:8px!important;line-height:1.25!important;white-space:normal!important;}
.hybrid-race-scroll>label>span:last-child{min-width:0;overflow-wrap:anywhere;}
.hybrid-race-footer{display:grid;grid-template-columns:minmax(150px,1fr) auto;align-items:center;gap:10px;padding:9px 11px;border-top:1px solid rgba(88,118,139,.62);background:linear-gradient(180deg,rgba(12,20,27,.98),rgba(6,10,15,.99));box-shadow:0 -9px 22px rgba(0,0,0,.28);}
.hybrid-race-status{min-width:0;color:#91a9b7;font-size:.72rem;line-height:1.3;}
.hybrid-race-actions{display:flex;align-items:center;justify-content:flex-end;gap:7px;}
.hybrid-race-actions button{min-height:32px;padding:6px 10px;border-radius:8px;font:800 .7rem var(--font-default);cursor:pointer;white-space:nowrap;}
.hybrid-race-secondary{border:1px solid rgba(92,106,118,.66);background:#111820;color:#b7c2ca;}
.hybrid-race-confirm{border:1px solid rgba(76,194,231,.82);background:linear-gradient(180deg,#174a60,#0b2735);color:#e8faff;box-shadow:0 0 16px rgba(67,193,236,.12);}
.hybrid-race-confirm:disabled{opacity:.38;cursor:not-allowed;box-shadow:none;}
/* Emekliye ayrılan eski arayüz parçaları hiçbir CSS gecikmesinde görünemez. */
[data-retired-ui]{display:none!important;visibility:hidden!important;pointer-events:none!important;contain:strict!important;}
@media(max-width:720px){.hybrid-race-footer{grid-template-columns:1fr}.hybrid-race-actions{justify-content:stretch}.hybrid-race-actions button{flex:1}.hybrid-race-scroll{grid-template-columns:1fr}}
`;

