const v62HybridResetAndMeggyBreathStyle=document.createElement("style");
v62HybridResetAndMeggyBreathStyle.id="alekV62HybridResetAndMeggyBreathStyle";
v62HybridResetAndMeggyBreathStyle.textContent=`
/* v62 · Meggy portresi: sert yanıp sönme değil, yumuşak ve hafif aura nefesi */
@keyframes v62MeggyAuraBreath{
  0%,100%{filter:brightness(1) saturate(1);box-shadow:0 0 0 7px rgba(14,51,68,.48),0 0 0 8px rgba(198,161,88,.28),0 0 34px rgba(77,198,239,.24)}
  50%{filter:brightness(1.055) saturate(1.045);box-shadow:0 0 0 7px rgba(18,66,88,.58),0 0 0 8px rgba(222,184,99,.39),0 0 48px rgba(92,211,250,.38)}
}
@keyframes v62MeggyPortraitBreath{
  0%,100%{opacity:.965;filter:brightness(.99) saturate(1)}
  50%{opacity:1;filter:brightness(1.05) saturate(1.035)}
}
.meggy-orb{animation:v62MeggyAuraBreath 3.2s cubic-bezier(.45,0,.55,1) infinite!important;will-change:filter,box-shadow}
.meggy-orb img{animation:v62MeggyPortraitBreath 3.2s cubic-bezier(.45,0,.55,1) infinite!important;will-change:filter,opacity}
@media(prefers-reduced-motion:reduce){.meggy-orb,.meggy-orb img{animation:none!important}}
`;
