    const speeds=members.map(item=>Number(item.entity.travelSpeed)).filter(value=>Number.isFinite(value)&&value>0);
    const visions=members.map(item=>Number(item.entity.visionRange)).filter(value=>Number.isFinite(value)&&value>=0);
