revision38FourCardBehaviorStyle.textContent=`
.journey-container-tabs{grid-template-columns:repeat(var(--tab-count,5),minmax(112px,1fr))!important;overflow-x:auto!important}
.container-resource-console{display:grid;gap:12px;padding:14px;border:1px solid rgba(83,132,153,.52);border-radius:12px;background:linear-gradient(145deg,rgba(8,24,33,.96),rgba(4,10,15,.98));box-shadow:inset 0 1px rgba(255,255,255,.035),0 12px 30px rgba(0,0,0,.28)}
.container-resource-console.collective{border-color:rgba(73,173,210,.54)}
.container-resource-console.institution{border-color:rgba(213,178,92,.58);background:linear-gradient(145deg,rgba(28,22,10,.92),rgba(8,9,12,.98))}
.container-resource-title{display:flex;align-items:flex-end;justify-content:space-between;gap:14px}.container-resource-title>div{display:grid;gap:3px}.container-resource-title small{color:#6ebbd8;font-size:.62rem;font-weight:900;letter-spacing:.14em}.container-resource-title strong{color:#edf7fa;font:800 1rem Georgia,serif}.container-resource-title>span{color:#8ca5b1;font-size:.7rem;text-align:right}
.container-total-bars{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.container-total-resource{display:grid;gap:7px;padding:10px;border:1px solid rgba(82,111,125,.48);border-radius:10px;background:#061018}.container-total-resource>div:first-child{display:flex;align-items:center;justify-content:space-between;gap:10px}.container-total-resource small{color:#a8bac3;font-size:.62rem;font-weight:900;letter-spacing:.1em}.container-total-resource strong{color:#eef7fa;font-size:.78rem}.container-total-track{height:12px!important;overflow:hidden;border-radius:999px;background:#02070b;box-shadow:inset 0 0 8px rgba(0,0,0,.9)}.container-total-track i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#7f1e36,#ff6782);box-shadow:0 0 12px rgba(255,79,115,.35)}.container-total-resource.mana .container-total-track i{background:linear-gradient(90deg,#135b7c,#53d7ff);box-shadow:0 0 12px rgba(72,199,244,.35)}.container-total-resource.influence .container-total-track i{background:linear-gradient(90deg,#69531d,#e6c25c);box-shadow:0 0 12px rgba(225,190,82,.35)}.container-total-resource.reputation .container-total-track i{background:linear-gradient(90deg,#4d356f,#c18df4);box-shadow:0 0 12px rgba(185,126,239,.35)}
.container-resource-actions{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}.container-resource-actions label{display:grid;gap:5px;color:#8fa5af;font-size:.66rem}.container-resource-actions input{width:100%;min-width:0;height:36px;box-sizing:border-box;border:1px solid #405b69;border-radius:8px;background:#03090d;color:#eef8fb;padding:6px 9px;outline:none}.container-resource-actions input:focus{border-color:#69c7e9;box-shadow:0 0 0 3px rgba(81,183,223,.12)}
.container-roster-section{display:grid;gap:10px}.container-navigation-grid.roster{grid-template-columns:repeat(auto-fill,minmax(285px,1fr))}
.container-inline-character-shell{position:relative;display:grid;grid-template-columns:112px minmax(0,1fr);gap:12px;min-height:560px;padding:12px;border:1px solid rgba(78,125,145,.5);border-radius:12px;background:linear-gradient(150deg,#09151d,#04090d 76%);overflow:hidden}
.container-inline-character-shell>.aeryth-rail{position:relative!important;inset:auto!important;width:100%!important;height:auto!important;min-height:530px!important;box-sizing:border-box!important;border-radius:10px!important;z-index:1!important;display:grid!important}
.container-inline-character-main{min-width:0;display:flex;flex-direction:column;gap:10px;overflow:visible}.container-inline-character-main>.character-identity-vitals{padding-right:0!important}.container-inline-sheet-body{min-width:0;min-height:0;overflow:visible;padding:0 3px 12px}.container-inline-sheet-body .character-sheet-layout{min-width:0}.container-inline-character-shell .character-sheet-identity-dock{min-width:0}.container-inline-character-shell :is(input,textarea,select,button){pointer-events:auto!important}
.container-inline-institution-shell{display:flex;flex-direction:column;gap:12px;min-height:560px;padding:12px;border:1px solid rgba(205,169,82,.48);border-radius:12px;background:linear-gradient(150deg,#191509,#06090d 74%)}.container-inline-institution-shell>.institution-identity-vitals{padding-right:0!important}.institution-resource-decks{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.institution-resource-deck{display:grid;gap:8px;padding:10px;border:1px solid rgba(205,169,82,.4);border-radius:10px;background:rgba(10,10,8,.78)}.institution-resource-deck>div:first-child{display:flex;align-items:center;justify-content:space-between}.institution-resource-deck strong{color:#e9d18b;font-size:.72rem;letter-spacing:.08em}.institution-resource-deck span{color:#f0e8d1;font-size:.72rem}.institution-resource-meter{height:9px;overflow:hidden;border-radius:999px;background:#030405!important}.institution-resource-meter i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#6b541e,#e0bd58);box-shadow:0 0 12px rgba(224,188,82,.32)}.institution-resource-deck.reputation .institution-resource-meter i{background:linear-gradient(90deg,#4d356e,#bd8bef);box-shadow:0 0 12px rgba(185,126,239,.32)}.institution-resource-inputs{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.institution-resource-inputs label{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:5px;color:#9d9174;font-size:.62rem}.institution-resource-inputs input{width:100%;min-width:0;height:32px;box-sizing:border-box;border:1px solid #5c5035;border-radius:7px;background:#080806;color:#f4edda;padding:4px 7px}
.journey-card-resource-strip{position:absolute;left:8%;right:8%;bottom:28.8%;z-index:84;display:grid;gap:4px;padding:6px 8px;border:1px solid rgba(86,154,181,.3);border-radius:8px;background:rgba(2,9,14,.88);backdrop-filter:blur(4px);box-shadow:0 7px 18px rgba(0,0,0,.38)}
.journey-card-resource-strip.institution{border-color:rgba(206,174,94,.36);background:rgba(17,13,5,.9)}.journey-card-resource-strip>span{display:grid;grid-template-columns:44px minmax(0,1fr) 48px;align-items:center;gap:6px}.journey-card-resource-strip small{color:#a8bec8;font-size:.5rem;font-weight:900;letter-spacing:.08em}.journey-card-resource-strip i{display:block;height:5px;overflow:hidden;border-radius:999px;background:#03070a}.journey-card-resource-strip b{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#7d2239,#ff6680)}.journey-card-resource-strip span:nth-child(2) b{background:linear-gradient(90deg,#145777,#52d3fb)}.journey-card-resource-strip.institution span:first-child b{background:linear-gradient(90deg,#6b541e,#e2bf5d)}.journey-card-resource-strip.institution span:nth-child(2) b{background:linear-gradient(90deg,#4d356e,#bd8bef)}.journey-card-resource-strip em{color:#d9e8ed;font-size:.5rem;font-style:normal;text-align:right;font-variant-numeric:tabular-nums}
@media(max-width:900px){.institution-resource-decks{grid-template-columns:1fr}.container-inline-character-shell{grid-template-columns:1fr}.container-inline-character-shell>.aeryth-rail{min-height:300px!important;grid-template-columns:1fr 1fr!important}.container-total-bars,.container-resource-actions{grid-template-columns:1fr 1fr}.container-resource-title{align-items:flex-start;flex-direction:column}.container-resource-title>span{text-align:left}.journey-container-tabs{grid-template-columns:repeat(var(--tab-count,5),minmax(105px,1fr))!important}}
@media(max-width:560px){.container-total-bars,.container-resource-actions{grid-template-columns:1fr}.journey-card-resource-strip{left:9%;right:9%}}
`;
