;(()=>{if(document.getElementById("alek-r126-frame-input-scroll-data"))return;const style=document.createElement("style");style.id="alek-r126-frame-input-scroll-data";style.textContent=`/* ========================================================================
   Tüp kalınlığı sabit, çerçeve/boşluk sıkı, 3 W hedefi, özgün Metanet
   ======================================================================== */
#alekLegacyMainPanel.character-detail-open>.character-detail-panel{
  grid-template-columns:176px minmax(0,1fr)!important;gap:0!important;margin-left:-1px!important;
}
#alekLegacyMainPanel.character-detail-open .aeryth-rail{
  grid-template-columns:repeat(4,44px)!important;width:176px!important;min-width:176px!important;
  gap:0!important;padding:0!important;margin:0!important;border:0!important;background:#070b10!important;
}
#alekLegacyMainPanel.character-detail-open .aeryth-rail>.vertical-resource{
  width:44px!important;min-width:44px!important;max-width:44px!important;box-sizing:border-box!important;
  padding:6px 0!important;margin:0!important;border-radius:7px!important;
}
#alekLegacyMainPanel.character-detail-open .vertical-resource-meter{
  width:24px!important;min-width:24px!important;max-width:24px!important; /* TÜP KALINLIĞI KORUNDU */
}
#alekLegacyMainPanel.character-detail-open .character-detail-content{padding-left:4px!important;}
#alekLegacyMainPanel.character-detail-open>#activeAvatar{margin-right:0!important;border-top-right-radius:0!important;border-bottom-right-radius:0!important;}

/* Sağ üst altılı küme: daha küçük düğme, daha ferah aralık, taşma yok. */
.character-header-actions{top:7px!important;right:7px!important;width:70px!important;min-width:70px!important;gap:6px!important;padding:0!important;}
.character-header-life-actions,
.character-header-rune-dock .character-sheet-rune-actions,
.character-header-rune-dock .persistent-header-runes{
  grid-template-columns:repeat(2,32px)!important;grid-auto-rows:32px!important;gap:6px!important;width:70px!important;min-width:70px!important;
}
.character-header-rune-dock{width:70px!important;min-width:70px!important;}
.character-header-actions :is(button,.rune-square-button,.character-sheet-rune-action){
  width:32px!important;height:32px!important;min-width:32px!important;min-height:32px!important;max-width:32px!important;max-height:32px!important;
  border-radius:9px!important;padding:0!important;font-size:.82rem!important;line-height:1!important;display:grid!important;place-items:center!important;
}
.character-header-actions svg{width:18px!important;height:18px!important;}
#alekLegacyMainPanel.character-detail-open .character-identity-vitals{padding-right:78px!important;}

/* Metanet artış/düşüş izi artık nötr gri değil, kendi canlı yeşil/ayçeliği ailesidir. */
.metanet-reservoir-fill .energy-flow-canvas{filter:none!important;}
.metanet-reservoir-lag{background:linear-gradient(180deg,rgba(225,255,181,.72),rgba(89,176,72,.54) 46%,rgba(24,84,58,.58))!important;box-shadow:0 0 15px rgba(139,244,105,.32)!important;}
.metanet-rail-reservoir[data-impact="increase"] .metanet-reservoir-lag{background:linear-gradient(180deg,rgba(246,255,215,.9),rgba(133,230,91,.74),rgba(37,123,79,.66))!important;box-shadow:0 0 20px rgba(155,255,116,.55)!important;}
.metanet-rail-reservoir[data-impact="decrease"] .metanet-reservoir-lag{background:linear-gradient(180deg,rgba(191,244,154,.68),rgba(69,147,67,.58),rgba(19,66,50,.7))!important;}

/* Üç hedef tek satırda: okyanus, Karayip ormanı, altın/turuncu. */
.mevcudat-drop-targets{display:grid!important;grid-template-columns:repeat(3,minmax(0,1fr))!important;gap:8px!important;align-items:stretch!important;}
.mevcudat-drop-targets>button{min-width:0!important;height:100%!important;grid-template-columns:36px minmax(0,1fr) 25px!important;gap:8px!important;padding:8px 9px!important;border-radius:11px!important;}
.mevcudat-drop-targets strong{font-size:clamp(.65rem,.72vw,.78rem)!important;white-space:normal!important;line-height:1.05!important;}
.mevcudat-drop-targets small{font-size:.49rem!important;}.mevcudat-drop-targets em{font-size:.54rem!important;white-space:nowrap!important;overflow:hidden!important;text-overflow:ellipsis!important;}
.mevcudat-drop-targets kbd{width:23px!important;height:23px!important;font-size:.6rem!important;}
.mevcudat-action-sigil{width:34px!important;height:34px!important;display:grid!important;place-items:center!important;border-radius:50%!important;}
.mevcudat-action-sigil svg{width:20px!important;height:20px!important;fill:none!important;stroke:currentColor!important;stroke-width:1.8!important;stroke-linecap:round!important;stroke-linejoin:round!important;}
.mevcudat-current-card-up-target{--gold:#ffb84d;display:grid;align-items:center;width:100%;border:1px solid rgba(255,184,77,.72);background:radial-gradient(circle at 12% 50%,rgba(255,184,77,.22),transparent 34%),linear-gradient(145deg,#3b2509,#171006 74%);color:#fff2d2;text-align:left;cursor:pointer;box-shadow:inset 0 0 24px rgba(255,174,55,.1),0 8px 20px rgba(0,0,0,.25);}
.mevcudat-current-card-up-target:hover:not(:disabled){border-color:#ffd187;box-shadow:inset 0 0 28px rgba(255,184,77,.17),0 0 17px rgba(255,167,49,.18);}
.mevcudat-current-card-up-target:disabled{opacity:.42;cursor:not-allowed;filter:saturate(.55);}
.mevcudat-current-card-up-sigil{border:1px solid rgba(255,208,126,.76);color:#ffd17f;background:radial-gradient(circle,#5a3510,#1a1005);}
.mevcudat-current-card-up-target small{color:#ffc66c;letter-spacing:.11em}.mevcudat-current-card-up-target strong{color:#fff0cf;font-family:Georgia,serif}.mevcudat-current-card-up-target em{color:#caa873;font-style:normal}.mevcudat-current-card-up-target kbd{display:grid;place-items:center;border:1px solid #ffc15c;border-radius:7px;background:#130c04;color:#ffd68d;font:900 .68rem ui-monospace,Consolas;}

/* Melez seçim paneli daima tam açılır; kendi içinde scroll üretmez. */
.living-hybrid-race-panel,.living-hybrid-race-list{max-height:none!important;height:auto!important;overflow:visible!important;}
.living-hybrid-race-actions{position:static!important;display:grid!important;grid-template-columns:repeat(3,minmax(92px,1fr))!important;gap:8px!important;}

/* CPU/RAM profili: pahalı canlı filtreleri azaltır, tüp raster katmanlarını korur. */
html[data-alek-performance="cpu-ram"] :is(.vertical-resource,.mevcudat-drop-targets>button,.character-header-actions button){backdrop-filter:none!important;-webkit-backdrop-filter:none!important;will-change:auto!important;}
@media(max-width:1120px){
  #alekLegacyMainPanel.character-detail-open>.character-detail-panel{grid-template-columns:176px minmax(0,1fr)!important;}
  .mevcudat-drop-targets{grid-template-columns:repeat(3,minmax(180px,1fr))!important;overflow-x:auto!important;padding-bottom:4px!important;}
}
`;document.head.appendChild(style);})();



