;(()=>{
  if(window.__ALEK_R31_INERT_TITLE_INSTALLED__)return;
  window.__ALEK_R31_INERT_TITLE_INSTALLED__=true;

  const STYLE_ID="alek-r31-inert-title-style";
  const TITLE_ID="alek-r31-inert-title";

  if(!document.getElementById(STYLE_ID)){
    const style=document.createElement("style");
    style.id=STYLE_ID;
    style.textContent=`
/* R31 · Sol üst Ałek’ryŧhæ imzası görsel title olarak kalır; hiçbir fare/kalem/dokunma girişini yakalamaz. */
#${TITLE_ID}{
  position:fixed!important;
  top:5px!important;
  left:13px!important;
  z-index:2147483600!important;
  width:112px!important;
  max-width:20vw!important;
  height:28px!important;
  object-fit:contain!important;
  object-position:left center!important;
  opacity:.82!important;
  filter:drop-shadow(0 0 5px rgba(170,225,255,.22))!important;
  pointer-events:none!important;
  user-select:none!important;
  -webkit-user-drag:none!important;
  touch-action:none!important;
}
@media(max-width:900px){#${TITLE_ID}{width:92px!important;height:24px!important;top:4px!important;left:9px!important}}
/* R37 · Filigran Cartographer’s Table’da kalır; yalnız JoA yaşayan haritasında görünmez. */
body:has(.joa-world-shell) #${TITLE_ID},
body:has(.journey-world-overlay) #${TITLE_ID}{display:none!important;}
`;
    document.head.appendChild(style);
  }

  const mount=()=>{
    if(document.getElementById(TITLE_ID)||!document.body)return;
    const logo=document.createElement("img");
    logo.id=TITLE_ID;
    logo.src="https://alek-assets.local/Assets/alekrythae_title.png";
    logo.alt="";
    logo.setAttribute("aria-hidden","true");
    logo.draggable=false;
    logo.tabIndex=-1;
    document.body.appendChild(logo);
  };

  mount();
  const observer=new MutationObserver(()=>mount());
  observer.observe(document.documentElement,{childList:true,subtree:true});
})();


